// ── Auth store (localStorage) ──────────────────
const AUTH_KEY  = 'baro_session';
const USERS_KEY = 'baro_users';

function getUsers() {
  try { return JSON.parse(localStorage.getItem(USERS_KEY)) || []; } catch { return []; }
}
function saveUsers(users) {
  localStorage.setItem(USERS_KEY, JSON.stringify(users));
}
function getSession() {
  try { return JSON.parse(localStorage.getItem(AUTH_KEY)); } catch { return null; }
}
function saveSession(user) {
  localStorage.setItem(AUTH_KEY, JSON.stringify(user));
}
function clearSession() {
  localStorage.removeItem(AUTH_KEY);
}

// ── Unit lists ────────────────────────────────
const UNITS = ['g','kg','t','ml','cl','l','m³','cm','m','m²','pce','lot','sac','carton','h','j','mois'];

const UNIT_COND = {
  'sac':    { label:'Contenance du sac',            opts:['25 kg','50 kg','100 kg','Autre'] },
  'lot':    { label:'Nombre de pièces par lot',      opts:['6','12','24','Autre'] },
  'carton': { label:"Nombre d'unités par carton",    opts:['6','12','24','48','Autre'] },
};

// ── Unit conversion helpers ───────────────────
const UNIT_FACTORS = { g:1,kg:1000,t:1e6, ml:1,cl:10,l:1000,'m³':1e6, cm:1,m:100, h:1,j:24,mois:720 };
const UNIT_GROUPS  = [['g','kg','t'],['ml','cl','l','m³'],['cm','m'],['h','j','mois']];

function compatibleUnits(unit) {
  const grp = UNIT_GROUPS.find(g => g.includes(unit));
  return grp || [unit];
}
// Échappement pour insertion dans un attribut HTML
function _attrEsc(v) {
  return String(v == null ? '' : v)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;')
    .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
// Repli sans accents ni casse : « crème » et « CREME » se valent.
// normalize() coûte cher et la plupart des libellés sont en ASCII pur :
// on ne le déclenche que si la chaîne contient réellement un accent.
function _fold(s) {
  s = String(s == null ? '' : s).toLowerCase();
  return /[^\x00-\x7F]/.test(s) ? s.normalize('NFD').replace(/[̀-ͯ]/g, '') : s;
}

// ── Recherche intelligente ────────────────────────────────────────────
// Découpe la saisie en mots : l'ordre n'a pas d'importance, et chaque mot
// doit se retrouver quelque part. « 500 doliprane » trouve « Doliprane 500 ».
function _searchTokens(q) {
  return _fold(q).split(/[^a-z0-9]+/).filter(Boolean);
}

// Vrai si les deux mots sont identiques à une faute près (ajout, oubli,
// remplacement ou inversion d'une lettre). Sortie anticipée, pas de matrice.
function _dist1(a, b) {
  if (a === b) return true;
  const la = a.length, lb = b.length;
  if (Math.abs(la - lb) > 1) return false;
  let i = 0, j = 0, diff = 0;
  while (i < la && j < lb) {
    if (a[i] === b[j]) { i++; j++; continue; }
    if (++diff > 1) return false;
    if (la > lb) i++;
    else if (lb > la) j++;
    else { i++; j++; }
  }
  if (i < la || j < lb) diff++;
  return diff <= 1;
}

// Note de pertinence d'un enregistrement (0 = ne correspond pas).
// Un mot entier vaut mieux qu'un début de mot, qui vaut mieux qu'un
// fragment ; la correspondance approchée passe en dernier.
function _matchScore(fields, tokens, fuzzy) {
  if (!tokens.length) return 0;
  const hay = _fold(fields.filter(Boolean).join(' '));
  if (!hay) return 0;
  let words = null, score = 0;
  for (const tk of tokens) {
    let best = 0;
    if (hay.includes(tk)) {
      if (words === null) words = hay.split(/[^a-z0-9]+/).filter(Boolean);
      best = words.includes(tk) ? 100 : words.some(w => w.startsWith(tk)) ? 60 : 25;
    } else if (fuzzy && tk.length >= 4) {
      if (words === null) words = hay.split(/[^a-z0-9]+/).filter(Boolean);
      if (words.some(w => _dist1(w, tk))) best = 10;
    }
    if (!best) return 0;   // tous les mots saisis doivent correspondre
    score += best;
  }
  return score;
}

// Classe une liste par pertinence. Second passage tolérant aux fautes
// uniquement si le premier ne donne rien : une saisie exacte n'est jamais
// polluée par des à-peu-près.
function smartSearch(list, fieldsOf, tokens, limit) {
  if (!tokens.length || !Array.isArray(list)) return [];
  for (const fuzzy of [false, true]) {
    const hits = [];
    for (const o of list) {
      const s = _matchScore(fieldsOf(o), tokens, fuzzy);
      if (s > 0) hits.push({ o, s });
    }
    if (hits.length) {
      hits.sort((a, b) => b.s - a.s);
      return hits.slice(0, limit).map(x => x.o);
    }
  }
  return [];
}
// Filtre la liste des ingrédients sans re-rendre la vue : les quantités
// déjà saisies restent dans le DOM, et les lignes remplies restent visibles.
function filterComposition(q) {
  const needle = _fold(q).trim();
  const rows = document.querySelectorAll('.comp-input');
  let shown = 0;
  rows.forEach(row => {
    const filled = !!(row.querySelector('.comp-qty') || {}).value;
    const match = !needle || _fold(row.dataset.name || '').includes(needle);
    const visible = filled || match;
    row.classList.toggle('comp-hidden', !visible);
    if (visible) shown++;
  });
  const empty = document.getElementById('comp-empty');
  if (empty) empty.style.display = shown ? 'none' : 'block';
  const count = document.getElementById('comp-count');
  if (count) {
    count.textContent = needle
      ? `${shown} sur ${rows.length} ingrédient${rows.length > 1 ? 's' : ''}`
      : `${rows.length} ingrédient${rows.length > 1 ? 's' : ''} disponible${rows.length > 1 ? 's' : ''}`;
  }
}
function convertQty(qty, from, to) {
  if (from === to) return qty;
  const f = UNIT_FACTORS[from], t = UNIT_FACTORS[to];
  if (!f || !t) return qty;
  const result = qty * f / t;
  return Math.abs(result) < 0.01 ? 0 : parseFloat(result.toPrecision(10));
}
function fmtQty(n) {
  if (n == null || Math.abs(n) < 0.01) return '0';
  return parseFloat(parseFloat(n).toFixed(4)).toString();
}

// ── API base ──────────────────────────────────
// Priorité : URL configurée dans Paramètres → Serveur (API) > override global > défaut.
// Permet de brancher un nouveau backend (Render/Railway) sans redéployer le front.
const _savedApiUrl = (() => { try { return (localStorage.getItem('baro_api_url') || '').trim().replace(/\/+$/, ''); } catch(_) { return ''; } })();
const API_BASE = (location.hostname === 'localhost' || location.hostname === '127.0.0.1')
  ? 'http://localhost:5001'
  : (_savedApiUrl || window.__BARO_API_URL__ || window.__STOCKR_API_URL__ || 'https://DakanStudios.pythonanywhere.com');

