// ── Fonctions mises en retrait pour le lancement ───────────────────────────
// Elles exigent une configuration externe payante (clé d'API d'un modèle de
// langage) : sans budget, elles ne peuvent pas être « 100 % vraies ». Plutôt
// que d'exposer une fonction creuse — ce qui fait rejeter sur les stores et
// déçoit l'utilisateur — on les masque partout : menu, accueil et navigation
// directe. Ce n'est PAS une suppression : vider ce Set les réactive telles
// quelles, sans rien réécrire.
const LAUNCH_HIDDEN = new Set(['ai-chat', 'video-library']);
function _isHidden(id) { return LAUNCH_HIDDEN.has(id); }

// ── Sécurité : toute ouverture d'onglet externe reçoit 'noopener' ──────────
// Sans cela, la page ouverte accède à window.opener et peut rediriger NOTRE
// onglet vers une fausse page de connexion (détournement d'onglet inversé).
// Exception : window.open('') — fenêtre vierge de même origine dans laquelle
// l'app écrit un aperçu ; 'noopener' renverrait null et casserait l'écriture.
(function () {
  if (typeof window === 'undefined' || window.__openHardened) return;
  const _open = window.open.bind(window);
  window.open = function (url, target, features) {
    if (!url) return _open(url, target, features);
    const f = features ? String(features) : '';
    return _open(url, target, /\bnoopener\b/.test(f) ? f : (f ? f + ',noopener' : 'noopener'));
  };
  window.__openHardened = true;
})();

// ── Empreinte de mot de passe (mode local) ─────────────────
// Les comptes locaux stockaient le mot de passe EN CLAIR dans localStorage :
// quiconque a accès à l'appareil (ou une faille XSS) pouvait tout lire, et les
// gens réutilisent leurs mots de passe. On stocke désormais une empreinte
// SHA-256 salée. Le sel est l'IDENTIFIANT du compte (stable) et non l'e-mail :
// sinon changer d'e-mail invaliderait l'empreinte et verrouillerait l'utilisateur
// définitivement, puisque le mot de passe en clair n'existe plus pour re-hacher.
// Les anciens comptes en clair sont migrés à leur prochaine connexion.
async function _pwdHash(salt, password) {
  const data = 'baro|v1|' + String(salt == null ? '' : salt) + '|' + String(password || '');
  try {
    if (crypto && crypto.subtle) {
      const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(data));
      return 'h1$' + Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('');
    }
  } catch (_) {}
  // Repli si SubtleCrypto indisponible (contexte non sécurisé) — moins solide,
  // mais toujours préférable au stockage en clair.
  let h1 = 0x811c9dc5, h2 = 5381;
  for (let i = 0; i < data.length; i++) {
    h1 = ((h1 ^ data.charCodeAt(i)) * 0x01000193) >>> 0;
    h2 = ((h2 << 5) + h2 + data.charCodeAt(i)) >>> 0;
  }
  return 'h0$' + h1.toString(16) + h2.toString(16);
}

function _localApi(method, path, body) {
  // ── Auth ──
  if (path === '/api/auth/register' && method === 'POST') {
    return (async () => {
      const users = _lsUsers();
      if (users.find(u => u.email === body.email)) throw new Error('Email déjà utilisé');
      const _uidNew = Date.now();
      const user = { id: _uidNew, email: body.email, _pwdh: await _pwdHash(_uidNew, body.password), name: body.name, business_name: body.business_name || body.name, currency: body.currency || 'XOF', country: body.country || 'SN', language: body.language || 'fr', profile: body.profile || 'transformer', tax_rate: parseFloat(body.tax_rate) || 0, auth_token: 'local_' + Date.now() };
      users.push(user);
      _lsSave(users);
      _lsSaveData(user.id, { articles: [], products: [], sales: [], clients: [] });
      return { user };
    })();
  }
  if (path === '/api/auth/login' && method === 'POST') {
    return (async () => {
      const users = _lsUsers();
      const u = users.find(x => x.email === body.email);
      let ok = false;
      if (u) {
        if (u._pwdh) {
          ok = u._pwdh === await _pwdHash(u.id, body.password);
        } else if (u._pwd !== undefined) {
          // Compte hérité en clair : on vérifie puis on migre immédiatement.
          ok = u._pwd === body.password;
          if (ok) { u._pwdh = await _pwdHash(u.id, body.password); delete u._pwd; _lsSave(users); }
        }
      }
      if (!ok) throw new Error('Email ou mot de passe incorrect');
      return { user: { ...u, auth_token: 'local_' + u.id } };
    })();
  }
  if (path === '/api/auth/profile' && method === 'GET') {
    return _lsUsers().find(u => u.id === _uid()) || {};
  }
  if (path === '/api/auth/profile' && method === 'PUT') {
    const users = _lsUsers(); const u = users.find(u => u.id === _uid());
    if (u) { Object.assign(u, body); _lsSave(users); }
    return u;
  }
  if (path === '/api/auth/logout' && method === 'POST') { return {}; }

  const d = _lsData(_uid());

  // ── Articles ──
  if (path === '/api/articles/' && method === 'GET') return d.articles;
  if (path === '/api/articles/' && method === 'POST') {
    // Stocker le corps COMPLET (image, sell_price, category, expiry…) — le
    // squelette 7 champs faisait "disparaître" photo/prix au redémarrage.
    const a = { quantity: 0, unit: 'pcs', alert_threshold: 0, lead_time_days: 7, daily_avg_demand: 0, ...body, id: Date.now() };
    d.articles.push(a); _lsSaveData(_uid(), d); return a;
  }
  const artId = path.match(/\/api\/articles\/(\d+)/)?.[1];
  if (artId && method === 'PUT') {
    const a = d.articles.find(a => a.id === parseInt(artId));
    if (a) { for (const k in body) { if (body[k] !== undefined) a[k] = body[k]; } _lsSaveData(_uid(), d); }
    return a;
  }
  if (artId && method === 'DELETE') {
    d.articles = d.articles.filter(a => a.id !== parseInt(artId)); _lsSaveData(_uid(), d); return {};
  }

  // ── Products ──
  if (path === '/api/products/' && method === 'GET') return d.products.map(p => ({ ...p, composition: (p.composition||[]).map(c => ({ article: d.articles.find(a=>a.id===c.article_id)||{id:c.article_id,name:'?',unit:'pcs'}, quantity_used: c.quantity_used })) }));
  if (path === '/api/products/' && method === 'POST') {
    // Corps complet ici aussi (image, category, description…)
    const p = { price: 0, purchase_price: 0, composition: [], ...body, id: Date.now() };
    d.products.push(p); _lsSaveData(_uid(), d);
    return { ...p, composition: p.composition.map(c => ({ article: d.articles.find(a=>a.id===c.article_id)||{id:c.article_id,name:'?',unit:'pcs'}, quantity_used: c.quantity_used })) };
  }
  const prodId = path.match(/\/api\/products\/(\d+)/)?.[1];
  if (prodId && method === 'PUT') {
    const p = d.products.find(p => p.id === parseInt(prodId));
    if (p) { for (const k in body) { if (body[k] !== undefined) p[k] = body[k]; } _lsSaveData(_uid(), d); }
    return { ...p, composition: (p.composition||[]).map(c => ({ article: d.articles.find(a=>a.id===c.article_id)||{id:c.article_id,name:'?',unit:'pcs'}, quantity_used: c.quantity_used })) };
  }
  if (prodId && method === 'DELETE') {
    d.products = d.products.filter(p => p.id !== parseInt(prodId)); _lsSaveData(_uid(), d); return {};
  }

  // ── Sales ──
  if (path === '/api/sales/' && method === 'GET') return d.sales;
  if (path === '/api/sales/' && method === 'POST') {
    const p = d.products.find(p => p.id === body.product_id);
    if (!p) throw new Error('Produit introuvable');
    for (const c of (p.composition||[])) {
      const art = d.articles.find(a => a.id === c.article_id);
      if (!art || art.quantity < c.quantity_used * body.quantity) throw new Error(`Stock insuffisant : ${art?.name||'?'}`);
    }
    for (const c of (p.composition||[])) {
      const art = d.articles.find(a => a.id === c.article_id);
      if (art) art.quantity = Math.round((art.quantity - c.quantity_used * body.quantity) * 10) / 10;
    }
    const sale = { id: Date.now(), product_id: body.product_id, product_name: p.name, quantity: body.quantity, client_id: body.client_id || null, client_name: body.client_name || null, timestamp: new Date().toISOString() };
    d.sales.unshift(sale); _lsSaveData(_uid(), d);
    return { sale };
  }

  // ── Clients ──
  if (!d.clients) d.clients = [];
  if (path === '/api/clients/' && method === 'GET') return d.clients;
  if (path === '/api/clients/' && method === 'POST') {
    const c = { id: Date.now(), name: body.name, phone: body.phone || '', email: body.email || '', notes: body.notes || '', created_at: new Date().toISOString() };
    d.clients.push(c); _lsSaveData(_uid(), d); return c;
  }
  const clientId = path.match(/\/api\/clients\/(\d+)/)?.[1];
  if (clientId && method === 'PUT') {
    const c = d.clients.find(c => c.id === parseInt(clientId));
    if (c) { c.name = body.name || c.name; c.phone = body.phone ?? c.phone; c.email = body.email ?? c.email; c.notes = body.notes ?? c.notes; _lsSaveData(_uid(), d); }
    return c;
  }
  if (clientId && method === 'DELETE') {
    d.clients = d.clients.filter(c => c.id !== parseInt(clientId)); _lsSaveData(_uid(), d); return {};
  }

  // ── Predictions (stub local) ──
  if (path === '/api/predictions/') return [];

  // ── Spectra (offline) — passerelle : la détection réelle se fait côté navigateur ──
  // via BarcodeDetector natif + TensorFlow.js/COCO-SSD. Le backend local reçoit
  // seulement les détections déjà calculées et les retourne (ou tableau vide).
  if (path === '/api/spectra/scan' && method === 'POST') {
    const detections = Array.isArray(body.detections) ? body.detections : [];
    return { detections };
  }
  if (path === '/api/spectra/confirm' && method === 'POST') {
    const results = [];
    for (const item of (body.items || [])) {
      const art = d.articles.find(a => a.id === item.article_id || a.name.toLowerCase() === item.name.toLowerCase());
      if (art) {
        art.quantity = (art.quantity || 0) + item.quantity;
        results.push({ name: art.name, new_qty: item.quantity, unit: art.unit || item.unit || 'pce' });
      } else {
        const newArt = { id: Date.now() + Math.floor(Math.random()*1000), name: item.name, quantity: item.quantity, unit: item.unit || 'pce', alert_threshold: 0, lead_time_days: 7 };
        d.articles.push(newArt);
        results.push({ name: item.name, new_qty: item.quantity, unit: item.unit || 'pce' });
      }
    }
    _lsSaveData(_uid(), d);
    return { results };
  }

  throw new Error('Route locale non supportée : ' + path);
}

// ── API helper ────────────────────────────────
// Traduit les messages d'erreur anglais du backend en français
function _frError(msg) {
  if (!msg || typeof msg !== 'string') return msg;
  const map = [
    [/product not found/i,        'Produit introuvable'],
    [/article not found/i,        'Article introuvable'],
    [/client not found/i,         'Client introuvable'],
    [/user not found/i,           'Compte introuvable'],
    [/not found/i,                'Introuvable'],
    [/insufficient stock/i,       'Stock insuffisant'],
    [/invalid credentials/i,      'Email ou mot de passe incorrect'],
    [/invalid token|unauthorized/i,'Session expirée — reconnectez-vous'],
    [/email already (exists|registered|taken)/i, 'Cet email est déjà utilisé'],
    [/password too short/i,       'Mot de passe trop court'],
    [/network error/i,            'Erreur réseau'],
    [/internal server error/i,    'Erreur serveur — réessayez'],
    [/bad request/i,              'Requête invalide'],
    [/forbidden/i,                'Accès refusé'],
    [/too many requests/i,        'Trop de tentatives — patientez un instant'],
  ];
  for (const [re, fr] of map) { if (re.test(msg)) return fr; }
  return msg;
}

// Délai maximum d'un appel réseau. Sans lui, sur une connexion mobile qui
// « pend » (courant en Afrique de l'Ouest), le navigateur attend sa valeur par
// défaut — jusqu'à plusieurs dizaines de secondes — et l'utilisateur reste
// devant un écran figé après avoir touché « S'inscrire » ou « Vendre ».
// Passé ce délai on abandonne et on bascule en local : l'app répond toujours.
const API_TIMEOUT_MS = 7000;
const API_TIMEOUT_LONG_MS = 30000;   // analyses d'image : légitimement plus lentes
function _apiTimeoutFor(path) {
  return /\/spectra\/|\/analyze|\/upload/i.test(path || '') ? API_TIMEOUT_LONG_MS : API_TIMEOUT_MS;
}

async function api(method, path, body) {
  if (USE_LOCAL) {
    try { return _localApi(method, path, body); }
    catch(e) { throw new Error(_frError(e.message)); }
  }
  const _ctrl = (typeof AbortController !== 'undefined') ? new AbortController() : null;
  const _timer = _ctrl ? setTimeout(() => _ctrl.abort(), _apiTimeoutFor(path)) : null;
  try {
    const res = await fetch(API_BASE + path, {
      method,
      headers: { 'Content-Type': 'application/json', ...(S.token ? { 'Authorization': `Bearer ${S.token}` } : {}) },
      body: body ? JSON.stringify(body) : undefined,
      ...(_ctrl ? { signal: _ctrl.signal } : {})
    });
    if (_timer) clearTimeout(_timer);
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      const raw = typeof err.error === 'string' ? err.error : (err.error?.error || err.message || `Erreur ${res.status}`);
      // Backend indisponible (serveur non déployé → 404 "Application not found",
      // ou erreur 5xx) : bascule transparente en mode local pour ne jamais bloquer
      // l'inscription / connexion / sauvegarde. Les vraies erreurs métier (401, 409…)
      // sont, elles, bien remontées.
      if (res.status >= 500 || res.status === 404 || /application not found|not found/i.test(raw)) {
        if (!USE_LOCAL) { USE_LOCAL = true; try { showToast(t('offlineMode'), ''); } catch(_){} }
        return _localApi(method, path, body);
      }
      throw new Error(_frError(raw));
    }
    return res.json();
  } catch(e) {
    if (_timer) clearTimeout(_timer);
    // AbortError = notre délai maximum a expiré (réseau qui pend) → même
    // traitement qu'une panne réseau : bascule locale, l'app reste utilisable.
    const estReseau = e.name === 'AbortError' || e.message === 'Failed to fetch' ||
                      e.name === 'TypeError' || e.message.includes('503') ||
                      e.message.includes('Load failed') || e.message.includes('NetworkError');
    if (estReseau) {
      USE_LOCAL = true;
      showToast(t('offlineMode'), '');
      return _localApi(method, path, body);
    }
    throw e;
  }
}

// ── Mapping API → state ───────────────────────
// ── Sauvegarde/restauration de la CONFIGURATION sur le serveur ──
// Poussée à chaque démarrage connecté ; restaurée automatiquement sur un
// appareil vierge (changement de téléphone). JAMAIS de mots de passe ni de
// données métier (articles/ventes/clients/dépenses ont leurs propres tables).
async function _syncStoreBackup() {
  if (USE_LOCAL || !S.token) return;
  const EXCLUDE = /^(stockr_articles|baro_articles|stockr_products|stockr_sales|stockr_clients|baro_clients|baro_expenses|baro_users_v2|stockr_session|baro_api_url|stockr_eanDB|baro_spectra_history|baro_activities|baro_local_data|baro_myorders|baro_payment_history|baro_movements|baro_last_sync)/;
  const _collect = () => {
    const blob = {};
    let total = 0;
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (!/^(baro|stockr)_/.test(k) || EXCLUDE.test(k)) continue;
      const v = localStorage.getItem(k);
      if (v == null || v.length > 300000) continue; // jamais d'énormes valeurs (photos produits)
      if (total + v.length > 1500000) break;
      total += v.length;
      blob[k] = v;
    }
    return blob;
  };
  try {
    const srv = await api('GET', '/api/store/');
    // Appareil vierge (rien de configuré localement) + sauvegarde serveur → restauration
    const localVide = !(S.teamMembers || []).length && !(S.suppliers || []).length
      && !((S.boutiqueConfig || {}).name)
      && !(((S.boutiqueConfig || {}).articles || []).length)
      && !(((S.boutiqueConfig || {}).products || []).length);
    if (srv && srv.data && localVide) {
      let blob = null; try { blob = JSON.parse(srv.data); } catch(_){}
      if (blob && Object.keys(blob).length) {
        Object.keys(blob).forEach(k => { try { localStorage.setItem(k, blob[k]); } catch(_){} });
        showToast('☁️ Configuration restaurée depuis votre compte', 'success');
        setTimeout(() => location.reload(), 900);
        return;
      }
    }
    // Sinon : miroir du local vers le serveur (sauvegarde du dernier démarrage)
    await api('PUT', '/api/store/', { data: JSON.stringify(_collect()) });
  } catch (e) { /* hors-ligne / serveur absent : silencieux */ }
}

// ── Commandes de la boutique en ligne : récupère celles reçues sur le site ──
// Le serveur fait foi pour ce qu'il connaît (id 'srv_') ; les commandes
// saisies manuellement dans l'app sont conservées.
async function _syncBoutiqueOrders() {
  if (USE_LOCAL || !S.token) return;
  try {
    const srv = await api('GET', '/api/orders/');
    if (!Array.isArray(srv)) return;
    const cur = S.boutiqueOrders || [];
    const localOnly = cur.filter(o => o && !String(o.id).startsWith('srv_'));
    const mapped = srv.map(o => ({ ...o, id: 'srv_' + o.id, serverId: o.id }));
    const before = cur.filter(o => String(o.id).startsWith('srv_')).length;
    S.boutiqueOrders = [...mapped, ...localOnly].sort((a, b) => new Date(b.date || 0) - new Date(a.date || 0));
    try { localStorage.setItem('baro_boutique_orders', JSON.stringify(S.boutiqueOrders)); } catch(_){}
    const newCount = mapped.length - before;
    if (newCount > 0) { showToast(`🛍️ ${newCount} nouvelle(s) commande(s) reçue(s) en ligne`, 'success'); render(); }
  } catch (e) { /* hors-ligne / serveur absent : silencieux */ }
}

// Persistance articles : TOUJOURS les deux clés historiques en même temps.
// (Des chemins n'écrivaient que baro_articles, d'autres que stockr_articles →
// selon le dernier écrivain, photo/prix disparaissaient au redémarrage.)
function _saveArticles() {
  try {
    const j = JSON.stringify(S.articles || []);
    localStorage.setItem('stockr_articles', j);
    localStorage.setItem('baro_articles', j);
  } catch(_){}
}
// Même règle que pour les articles : le démarrage relit `stockr_products` et
// `stockr_sales`. Écrire uniquement les clés `baro_*` faisait DISPARAÎTRE les
// produits et l'historique des ventes au redémarrage — le bug historique
// « je quitte l'app et mes trucs ne sont plus là ». On écrit donc les deux.
function _saveProducts() {
  try {
    const j = JSON.stringify(S.products || []);
    localStorage.setItem('stockr_products', j);
    localStorage.setItem('baro_products', j);
  } catch(_){}
}
function _saveSales() {
  try {
    const j = JSON.stringify(S.sales || []);
    localStorage.setItem('stockr_sales', j);
    localStorage.setItem('baro_sales', j);
  } catch(_){}
}

// Normalise les produits venant du stockage local ou du serveur : un produit
// hérité (ancienne version, import, saisie partielle) peut ne pas avoir de
// `composition`, ce qui faisait planter toute la vue Produits (13 accès directs).
function _normalizeProducts(list) {
  if (!Array.isArray(list)) return [];
  list.forEach(p => { if (p && !Array.isArray(p.composition)) p.composition = []; });
  return list;
}

function articleFromAPI(a) {
  const o = {
    id: a.id, name: a.name, stock: a.quantity, unit: a.unit,
    min: a.alert_threshold || 0, lead: a.lead_time_days,
    ref: a.ref || '',
    price: a.price || 0,
    purchasePrice: a.purchase_price || 0,
    sellPrice: a.sell_price || 0,
    category: a.category || '',
    perishable: !!a.perishable,
    expiry: a.expiry || '',
    image: a.image || '',
    ean: a.ean || '',
    description: a.description || ''
  };
  // Champs synchronisés (Lot 133) — posés seulement si non vides pour laisser
  // __applyExtras compléter depuis le local sinon
  if (Array.isArray(a.variants) && a.variants.length) o.variants = a.variants;
  if (a.in_boutique) o.inBoutique = true;
  return o;
}
function productFromAPI(p) {
  return {
    id: p.id, name: p.name, price: p.price, purchasePrice: p.purchase_price || 0,
    composition: (p.composition || []).map(c => ({ id: c.article.id, qty: c.quantity_used }))
  };
}
function marginPct(p) {
  return p.price > 0 ? Math.round(((p.price - p.purchasePrice) / p.price) * 100) : 0;
}
function profitUnit(p) {
  return p.price - p.purchasePrice;
}
function saleFromAPI(s) {
  const product = S.products.find(p => p.id === s.product_id);
  const price = product ? product.price : 0;
  const cost  = product ? product.purchasePrice : 0;
  return { id: s.id, productId: s.product_id, productName: s.product_name, qty: s.quantity, total: price * s.quantity, profit: (price - cost) * s.quantity, date: s.timestamp, clientId: s.client_id || null, clientName: s.client_name || null };
}

// ── Charger données depuis l'API ──────────────
async function loadData() {
  // Lire d'abord les données locales comme fallback garanti
  const local = {
    articles: (() => { try {
      // Fusionne les deux stockages historiques (stockr_articles + baro_articles) par id —
      // le bouton Vendre & co n'écrivaient que baro_articles alors qu'on ne lisait que
      // stockr_articles → photo/prix "disparaissaient" au redémarrage. Champ par champ,
      // la valeur non vide gagne (photo et prix survivent quel que soit le dernier écrivain).
      const a = JSON.parse(localStorage.getItem('stockr_articles') || '[]');
      const b = JSON.parse(localStorage.getItem('baro_articles')   || '[]');
      const map = {};
      [...a, ...b].forEach(x => {
        if (!x || x.id == null) return;
        if (!map[x.id]) { map[x.id] = { ...x }; return; }
        const m = map[x.id];
        for (const k in x) { const v = x[k]; if (v !== undefined && v !== null && v !== '' && !(v === 0 && (m[k] || m[k] === 0))) m[k] = v; else if (m[k] === undefined) m[k] = v; }
      });
      return Object.values(map);
    } catch { return []; } })(),
    products: (() => { try { return JSON.parse(localStorage.getItem('stockr_products') || '[]'); } catch { return []; } })(),
    sales:    (() => { try { return JSON.parse(localStorage.getItem('stockr_sales')    || '[]'); } catch { return []; } })(),
    clients:  (() => { try {
      // Fusionne les deux stockages historiques (stockr_clients + baro_clients) par id —
      // un client créé pendant une vente était écrit dans baro_clients seulement et
      // pouvait "disparaître" au rechargement. On ne perd plus aucun client.
      const a = JSON.parse(localStorage.getItem('stockr_clients') || '[]');
      const b = JSON.parse(localStorage.getItem('baro_clients')   || '[]');
      const map = {}; [...a, ...b].forEach(c => { if (c && c.id != null) map[c.id] = { ...(map[c.id]||{}), ...c }; });
      return Object.values(map);
    } catch { return []; } })(),
  };

  // Pré-hydratation immédiate (pas d'écran vide pendant le fetch)
  const hasLocal = local.articles.length || local.products.length || local.sales.length || local.clients.length;
  if (hasLocal) {
    S.articles = local.articles;
    S.products = _normalizeProducts(local.products);
    S.sales    = local.sales;
    S.clients  = local.clients;
    try { recalcAllMins(); } catch(_){}
    render();
  } else {
    // Aucune donnée locale → skeletons pendant le fetch initial
    S.dataLoading = true;
    render();
  }

  // Statut d'abonnement serveur en parallèle (sans bloquer le chargement)
  try { _syncBillingStatus(); } catch(_){}
  // Sauvegarde/restauration de la configuration (boutique, équipe, fournisseurs…)
  try { _syncStoreBackup(); } catch(_){}
  // Commandes reçues sur la boutique en ligne (arrivent du site hébergé)
  try { _syncBoutiqueOrders(); } catch(_){}

  try {
    const [arts, prods, sales, preds, clients, srvExps] = await Promise.all([
      api('GET', '/api/articles/'),
      api('GET', '/api/products/'),
      api('GET', '/api/sales/'),
      api('GET', '/api/predictions/'),
      api('GET', '/api/clients/').catch(() => []),
      api('GET', '/api/expenses/').catch(() => null), // null = serveur sans dépenses / hors-ligne → on garde le local
    ]);
    // Dépenses : le serveur fait foi pour ce qu'il connaît ; les saisies
    // hors-ligne (sans serverId) sont conservées telles quelles.
    if (Array.isArray(srvExps)) {
      const srv = srvExps.map(e => ({ id: 'srv_' + e.id, serverId: e.id, label: e.label, amount: e.amount, category: e.category || 'Autre', date: e.date }));
      const localOnly = (S.expenses || []).filter(e => e && !e.serverId && !String(e.id).startsWith('srv_'));
      S.expenses = [...srv, ...localOnly].sort((a, b) => new Date(b.date) - new Date(a.date));
      try { localStorage.setItem('baro_expenses', JSON.stringify(S.expenses)); } catch(_){}
    }
    const apiArts    = (arts  || []).map(articleFromAPI);
    const apiProds   = (prods || []).map(productFromAPI);
    const apiSales   = (sales || []).map(saleFromAPI);
    const apiClients = clients || [];
    // Préserver TOUT ce que l'API/le shim local ne stocke pas : photos, prix
    // d'achat/vente, catégorie, EAN, péremption, vitrine, variantes, avis…
    // Sans ça, un rechargement "efface" la photo et le bloc Vendre (bug récurrent).
    const __extraMap = {};
    [...local.articles, ...local.products].forEach(x => { if (x && x.id != null) __extraMap[x.id] = x; });
    const __ARRAY_FIELDS  = ['images', 'variants', 'reviews'];
    const __SCALAR_FIELDS = ['image', 'sellPrice', 'purchasePrice', 'price', 'category', 'ean', 'ref', 'expiry', 'perishable', 'inBoutique', 'description', 'locationId'];
    const __applyExtras = o => {
      const e = __extraMap[o.id]; if (!e) return;
      __ARRAY_FIELDS.forEach(f => { if (Array.isArray(e[f]) && e[f].length && !(Array.isArray(o[f]) && o[f].length)) o[f] = e[f]; });
      // On ne comble que les valeurs VIDES côté API (null/undefined/''/0) — jamais d'écrasement d'une vraie valeur.
      __SCALAR_FIELDS.forEach(f => { if ((o[f] == null || o[f] === '' || o[f] === 0) && e[f] != null && e[f] !== '' && e[f] !== 0) o[f] = e[f]; });
    };
    apiArts.forEach(__applyExtras);
    apiProds.forEach(__applyExtras);
    // ── RÈGLE D'OR (Lot 133) : le serveur COMPLÈTE, il n'efface JAMAIS ──
    // Avant : S.articles = apiArts remplaçait tout → un article/vente/client créé
    // hors-ligne (ou via le repli local) DISPARAISSAIT dès que le serveur renvoyait
    // une liste non vide. Maintenant : tout élément local inconnu du serveur est
    // conservé, puis les articles locaux sont renvoyés au serveur en arrière-plan.
    const __ids = list => new Set(list.map(x => String(x.id)));
    const artIds = __ids(apiArts), prodIds = __ids(apiProds), saleIds = __ids(apiSales), cliIds = __ids(apiClients);
    const localOnlyArts = local.articles.filter(a => a && a.id != null && !artIds.has(String(a.id)));
    S.dataLoading = false;
    S.articles    = [...apiArts,    ...localOnlyArts];
    S.products    = _normalizeProducts([...apiProds,   ...local.products.filter(p => p && p.id != null && !prodIds.has(String(p.id)))]);
    S.sales       = [...apiSales,   ...local.sales.filter(s => s && s.id != null && !saleIds.has(String(s.id)))];
    S.predictions = preds || [];
    S.clients     = [...apiClients, ...local.clients.filter(c => c && c.id != null && !cliIds.has(String(c.id)))];
    recalcAllMins();
    // Ré-adoption serveur des articles locaux (asynchrone, jamais bloquant)
    if (localOnlyArts.length) { try { _reconcileLocalArticles(localOnlyArts); } catch(_){} }
    // Persister pour fallback offline
    try {
      _saveArticles();
      localStorage.setItem('stockr_products', JSON.stringify(S.products));
      localStorage.setItem('stockr_sales',    JSON.stringify(S.sales));
      _saveClients();
    } catch(_){}
    // Synchro serveur réussie → horodatage (affiché dans Paramètres)
    if (!USE_LOCAL) { try { localStorage.setItem('baro_last_sync', new Date().toISOString()); } catch(_){} }
    render();
  } catch(e) {
    // Offline / API indisponible → on a déjà pré-hydraté, on notifie juste
    S.dataLoading = false;
    if (hasLocal) {
      showToast('Mode hors-ligne', 'info');
    } else {
      showToast(t('errLoad'), 'error');
      render();
    }
  }
}

// ── Lot 133 : ré-adoption serveur des articles créés hors-ligne ──
// Chaque article local inconnu du serveur est POSTé avec toutes ses
// métadonnées ; en cas de succès, l'article adopte l'id serveur et les
// références (ventes, mouvements) sont remappées. Échec → réessai au
// prochain démarrage. Ne touche jamais aux photos (locales par choix).
async function _reconcileLocalArticles(list) {
  if (USE_LOCAL || !S.token || !Array.isArray(list) || !list.length) return;
  let adopted = 0;
  for (const art of list.slice(0, 50)) {
    try {
      const d = await api('POST', '/api/articles/', {
        name: art.name, quantity: art.stock || 0, unit: art.unit || 'pcs',
        alert_threshold: art.min || null, lead_time_days: art.lead || 7,
        ref: art.ref || null, price: art.price || 0,
        purchase_price: art.purchasePrice || 0, sell_price: art.sellPrice || 0,
        category: art.category || '', ean: art.ean || '',
        expiry: art.expiry || '', perishable: !!art.perishable,
        description: art.description || '', in_boutique: !!art.inBoutique,
        variants: Array.isArray(art.variants) ? art.variants : [],
      });
      // id > 1e10 = réponse du shim local (repli hors-ligne) → on ne remappe pas
      if (!d || d.id == null || d.id === art.id || Number(d.id) > 1e10) continue;
      const oldId = art.id, newId = d.id;
      const ref = (S.articles || []).find(a => a.id === oldId);
      if (ref) ref.id = newId;
      (S.sales || []).forEach(s => {
        if (s.articleId === oldId) s.articleId = newId;
        (s.items || []).forEach(it => { if (it.articleId === oldId) it.articleId = newId; });
      });
      (S.movements || []).forEach(m => { if (m.articleId === oldId) m.articleId = newId; });
      adopted++;
    } catch(_) { /* hors-ligne / serveur pas à jour → réessai au prochain démarrage */ }
  }
  if (adopted) {
    try {
      _saveArticles();
      localStorage.setItem('stockr_sales', JSON.stringify(S.sales));
      if (typeof _saveMovements === 'function') _saveMovements();
    } catch(_){}
    console.log(`[reconcile] ${adopted} article(s) local(aux) adoptés par le serveur`);
  }
}

// ── Helpers ───────────────────────────────────
const $ = id => document.getElementById(id);

function fmt(n) {
  return Math.round(n).toLocaleString('fr-FR');
}
function fmtCurrency(n) {
  const sym = S.session?.currency_symbol || 'FCFA';
  return `${fmt(n)} ${sym}`;
}
function fmtDate(iso) {
  const d = new Date(iso), now = new Date(), diff = now - d;
  if (diff < 60000)    return "À l'instant";
  if (diff < 3600000)  return `Il y a ${Math.floor(diff/60000)} min`;
  if (diff < 86400000) return `Il y a ${Math.floor(diff/3600000)} h`;
  return d.toLocaleDateString('fr-FR', { day:'numeric', month:'short' });
}
function initials(name) {
  // Robuste : un nom vide/absent (commerce pas encore nommé, client sans nom)
  // faisait planter TOUTE la vue appelante. On retombe sur un monogramme neutre.
  const parts = String(name == null ? '' : name).trim().split(/\s+/).filter(Boolean);
  if (!parts.length) return '?';
  return parts.slice(0, 2).map(w => w.charAt(0).toUpperCase()).join('');
}
// Avatar d'article/produit : photo si présente, sinon monogramme
function itemAvatar(item, extraStyle = '') {
  if (item && item.image) {
    return `<img src="${item.image}" alt="" class="article-avatar" style="object-fit:cover;padding:0;${extraStyle}">`;
  }
  return `<div class="article-avatar" style="${extraStyle}">${initials(item?.name || '?')}</div>`;
}
function stockStatus(stock, min) {
  if (stock === 0) return { label:'Rupture', cls:'st-out', icon:IC.xmark, bar:'out' };
  if (stock < min) return { label:'Faible',  cls:'st-low', icon:IC.warn,  bar:'low' };
  return               { label:'OK',       cls:'st-ok',  icon:IC.check, bar:''    };
}
function productMaxMake(product) {
  // Garde : un produit hérité (ou importé) peut ne pas avoir de composition —
  // sans ce test, toute la vue Produits plantait sur un seul enregistrement.
  if (!product || !Array.isArray(product.composition) || !product.composition.length) return 99;
  return Math.floor(Math.min(...product.composition.map(c => {
    const a = S.articles.find(x => x.id === c.id);
    return a ? a.stock / c.qty : 0;
  })));
}
function salesForPeriod() {
  const now = new Date();
  if (S.period==='today') return S.sales.filter(s => new Date(s.date).toDateString()===now.toDateString());
  if (S.period==='7d')    return S.sales.filter(s => new Date(s.date) >= new Date(now-7*86400000));
  if (S.period==='30d')   return S.sales.filter(s => new Date(s.date) >= new Date(now-30*86400000));
  return S.sales;
}
// Même découpage de période que les ventes, pour les dépenses du Bilan
function expensesForPeriod() {
  const now = new Date();
  const list = S.expenses || [];
  if (S.period==='today') return list.filter(e => new Date(e.date).toDateString()===now.toDateString());
  if (S.period==='7d')    return list.filter(e => new Date(e.date) >= new Date(now-7*86400000));
  if (S.period==='30d')   return list.filter(e => new Date(e.date) >= new Date(now-30*86400000));
  return list;
}
function addExpense() {
  const label  = ((($('exp-label')  || {}).value) || S.expLabel  || '').trim();
  const amount = Math.max(0, parseFloat(((($('exp-amount') || {}).value) || S.expAmount)) || 0);
  const cat    = ((($('exp-cat') || {}).value) || S.expCat || 'Autre');
  if (!label)      { showToast('Décrivez la dépense', 'error'); return; }
  if (amount <= 0) { showToast('Entrez le montant', 'error'); return; }
  S.expenses = S.expenses || [];
  const _exp = { id: Date.now(), label, amount, category: cat, date: new Date().toISOString() };
  S.expenses.unshift(_exp);
  localStorage.setItem('baro_expenses', JSON.stringify(S.expenses));
  // Synchro serveur (multi-appareils) — sans bloquer, sans bruit hors-ligne
  if (!USE_LOCAL && S.token) {
    api('POST', '/api/expenses/', { label, amount, category: cat, date: _exp.date })
      .then(r => { if (r && r.id) { _exp.serverId = r.id; localStorage.setItem('baro_expenses', JSON.stringify(S.expenses)); } })
      .catch(() => {});
  }
  logActivity('expense', `Dépense : ${label} — ${fmt(amount)} ${sym()}`);
  showToast(`💸 Dépense enregistrée — ${fmt(amount)} ${sym()}`, 'success');
  S.expLabel = ''; S.expAmount = ''; S.expCat = '';
  render();
}
function deleteExpense(id) {
  const e = (S.expenses || []).find(x => String(x.id) === String(id));
  if (!e) return;
  if (!confirm(`Supprimer la dépense « ${e.label} » (${fmt(e.amount)} ${sym()}) ?`)) return;
  S.expenses = S.expenses.filter(x => String(x.id) !== String(id));
  localStorage.setItem('baro_expenses', JSON.stringify(S.expenses));
  if (e.serverId && !USE_LOCAL && S.token) { api('DELETE', `/api/expenses/${e.serverId}`).catch(() => {}); }
  showToast('Dépense supprimée', 'info');
  render();
}

// ── Calcul seuil auto ─────────────────────────
// Somme des qty requises de cet article dans tous les produits
function recalcMin(articleId) {
  let total = 0;
  S.products.forEach(p => {
    const comp = p.composition.find(c => c.id === articleId);
    if (comp) total += comp.qty;
  });
  const art = S.articles.find(a => a.id === articleId);
  if (art && total > 0) art.min = total;
}
function recalcAllMins() {
  S.articles.forEach(a => recalcMin(a.id));
}

// ── Activity Feed ─────────────────────────────
function logActivity(type, detail, extra = {}) {
  const act = { id: Date.now(), type, detail, date: new Date().toISOString(), ...extra };
  S.activities.unshift(act);
  if (S.activities.length > 100) S.activities = S.activities.slice(0, 100);
  localStorage.setItem('baro_activities', JSON.stringify(S.activities));
}
function fmtTimeAgo(iso) {
  const diff = Date.now() - new Date(iso).getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return t('justNow');
  if (mins < 60) return `${mins} ${t('minutesAgo')}`;
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return `${hrs} ${t('hoursAgo')}`;
  return new Date(iso).toLocaleDateString(_lang === 'en' ? 'en-US' : 'fr-FR', { day:'numeric', month:'short' });
}

// ── Subscription Manager ──────────────────────
// ═══════════════════════════════════════════════════════════════
// ENCAISSEMENT DES ABONNEMENTS — liens de paiement hébergés
// (Stripe Payment Link / CinetPay / PayDunya / Wave — au choix du proprio)
// L'argent va sur le compte du PROPRIÉTAIRE de l'app. Aucun backend requis.
// ═══════════════════════════════════════════════════════════════
// Le proprio colle ses liens dans Réglages → Encaissement (stockés en local
// ET idéalement en dur ici pour que TOUS les utilisateurs les voient).
const BILLING_LINKS_DEFAULT = {
  // Exemple : starter:{ monthly:'https://buy.stripe.com/...', yearly:'...' }
  starter:    { monthly: '', yearly: '' },
  pro:        { monthly: '', yearly: '' },
  enterprise: { monthly: '', yearly: '' },
};
function _billingLinks() {
  let stored = {};
  try { stored = JSON.parse(localStorage.getItem('baro_billing_links') || '{}'); } catch(_) {}
  // Fusionne défaut (code) + config locale (proprio)
  const out = {};
  for (const p of ['starter','pro','enterprise']) {
    out[p] = {
      monthly: (stored[p]?.monthly || BILLING_LINKS_DEFAULT[p].monthly || '').trim(),
      yearly:  (stored[p]?.yearly  || BILLING_LINKS_DEFAULT[p].yearly  || '').trim(),
    };
  }
  return out;
}
function _billingLinkFor(planKey, billing) {
  const links = _billingLinks();
  return links[planKey]?.[billing] || links[planKey]?.monthly || '';
}
// Au retour du paiement : ?baro_paid=pro → active le plan
function _handlePaymentReturn() {
  try {
    const params = new URLSearchParams(location.search);
    const paid = params.get('baro_paid');
    if (paid && ['starter','pro','enterprise'].includes(paid)) {
      _doActivatePlan(paid, { trial: false, paid: true });
      showToast(`✅ Paiement reçu — plan ${paid.toUpperCase()} activé !`, 'success');
      // Nettoie l'URL
      params.delete('baro_paid');
      const clean = location.pathname + (params.toString() ? '?' + params.toString() : '');
      history.replaceState(null, '', clean);
      return true;
    }
  } catch(_) {}
  return false;
}

function activatePlan(planKey) {
  // Free plan = activation directe, sans confirmation
  if (planKey === 'free') {
    _doActivatePlan(planKey);
    return;
  }
  // Paid plan : proposer essai 14j OU paiement immédiat
  const prices = {
    starter:    { monthly: 5000,   yearly: 48000 },
    pro:        { monthly: 20000,  yearly: 192000 },
    enterprise: { monthly: 100000, yearly: 960000 },
  };
  const labels = { starter:'Starter', pro:'Professional', enterprise:'Enterprise' };
  const billing = S.subscription.billing || 'monthly';
  const price = prices[planKey]?.[billing] || 0;
  const label = labels[planKey] || planKey;

  // Modal de choix
  const modal = document.createElement('div');
  modal.id = '__planConfirmModal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:10000;display:flex;align-items:center;justify-content:center;padding:20px;animation:fadeIn .2s';
  modal.innerHTML = `
    <div style="background:var(--surface);border-radius:20px;padding:24px;max-width:420px;width:100%;box-shadow:0 20px 60px rgba(0,0,0,.3);animation:slideUp .3s">
      <div style="text-align:center;margin-bottom:18px">
        <div style="width:64px;height:64px;border-radius:50%;background:linear-gradient(135deg,var(--accent),#7C3AED);display:inline-flex;align-items:center;justify-content:center;font-size:32px;margin-bottom:10px">💎</div>
        <div style="font-size:20px;font-weight:900;color:var(--text-1)">Plan ${label}</div>
        <div style="font-size:14px;color:var(--text-3);margin-top:4px">${fmt(price)} ${sym()} / ${billing==='yearly'?'an':'mois'}</div>
      </div>
      <button class="btn btn-primary" style="width:100%;padding:14px;font-size:15px;font-weight:800;margin-bottom:8px" onclick="__planStartTrial('${planKey}')">
        🎁 Essai gratuit 14 jours
      </button>
      <button class="btn btn-ghost" style="width:100%;padding:14px;font-size:15px;font-weight:700;border:2px solid var(--accent);color:var(--accent);margin-bottom:8px" onclick="__planPayNow('${planKey}', ${price})">
        💳 Payer maintenant — ${fmt(price)} ${sym()}
      </button>
      <button class="btn btn-ghost" style="width:100%;padding:10px;font-size:13px;color:var(--text-3)" onclick="__planConfirmClose()">
        Annuler
      </button>
    </div>
  `;
  document.body.appendChild(modal);
}
function __planConfirmClose() {
  const m = document.getElementById('__planConfirmModal');
  if (m) m.remove();
}
function __planStartTrial(planKey) {
  __planConfirmClose();
  _doActivatePlan(planKey, { trial: true });
}
async function __planPayNow(planKey, amount) {
  __planConfirmClose();
  const billing = S.subscription.billing || 'monthly';
  // 0) Checkout serveur (Stripe abonnement / CinetPay) — le vrai débit automatique.
  //    Actif dès que le backend est déployé avec les clés de paiement.
  if (!USE_LOCAL && S.token) {
    try {
      const ck = await api('POST', '/api/billing/checkout', { plan: planKey, billing });
      if (ck && ck.url) {
        try { window.open(ck.url, '_blank'); } catch(_) { location.href = ck.url; }
        showToast('Page de paiement sécurisée ouverte (' + (ck.provider || 'paiement') + ')', '');
        return;
      }
    } catch(e) {
      // 501 = paiement non configuré côté serveur → replis locaux ci-dessous (honnête)
      if (!/non configur/i.test(e.message || '')) { showToast(e.message, 'error'); }
    }
  }
  // 1) Lien de paiement hébergé configuré (Stripe/CinetPay/PayDunya/Wave) → page sécurisée
  const link = _billingLinkFor(planKey, billing);
  if (link) {
    try { window.open(link, '_blank'); } catch(_) { location.href = link; }
    // Au retour (redirect ?baro_paid=plan), le plan s'active automatiquement.
    // En attendant, propose la confirmation manuelle (fallback si pas de redirect).
    setTimeout(() => __planShowConfirmModal(planKey, amount, 'lien'), 1200);
    return;
  }
  // 2) Sinon : Mobile Money / PayPal (USSD + confirmation)
  const active = (S.paymentMethods||[]).filter(m => m.active);
  if (active.length === 0) {
    // Pas de moyen configuré → ouvrir directement le choix des providers populaires
    __planShowPaymentPicker(planKey, amount);
    return;
  }
  // 1 seule méthode → l'utiliser directement
  if (active.length === 1) {
    await __planProcessPayment(active[0].provider, planKey, amount);
    return;
  }
  // Plusieurs méthodes → afficher un choix visuel
  __planShowMethodPicker(planKey, amount, active);
}

// Sélecteur visuel des moyens de paiement configurés
function __planShowMethodPicker(planKey, amount, active) {
  const LBL = { wave:'Wave', orange:'Orange Money', moov:'Moov Money', mtn:'MTN Mobile Money', paypal:'PayPal', gpay:'Google Pay', applepay:'Apple Pay', card:'Carte bancaire' };
  const ICON = { wave:'W', orange:'OM', moov:'MV', mtn:'MTN', paypal:'PP', gpay:'G', applepay:'', card:'CB' };
  const modal = document.createElement('div');
  modal.id = '__planMethodModal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:10000;display:flex;align-items:center;justify-content:center;padding:20px';
  modal.innerHTML = `
    <div style="background:var(--surface);border-radius:20px;padding:20px;max-width:400px;width:100%">
      <div style="font-size:18px;font-weight:900;text-align:center;margin-bottom:14px">Choisir un mode de paiement</div>
      <div style="font-size:13px;color:var(--text-3);text-align:center;margin-bottom:16px">${fmt(amount)} ${sym()} · Plan ${planKey.toUpperCase()}</div>
      ${active.map(m => `
        <button class="btn btn-ghost" style="width:100%;padding:14px;margin-bottom:8px;border:2px solid var(--border);font-weight:700;display:flex;align-items:center;gap:12px;justify-content:flex-start;font-size:14px" onclick="document.getElementById('__planMethodModal').remove();__planProcessPayment('${m.provider}', '${planKey}', ${amount})">
          <span style="font-size:13px;font-weight:800;color:var(--accent);min-width:28px">${ICON[m.provider]||''}</span>
          <span style="flex:1;text-align:left">${LBL[m.provider]||m.name}</span>
          ${m.phone ? `<span style="font-size:11px;color:var(--text-3)">${m.phone}</span>` : ''}
        </button>
      `).join('')}
      <button class="btn btn-ghost" style="width:100%;padding:10px;font-size:13px;color:var(--text-3);margin-top:4px" onclick="document.getElementById('__planMethodModal').remove()">Annuler</button>
    </div>
  `;
  document.body.appendChild(modal);
}

// Sélecteur de provider quand aucun n'est configuré (démarre avec des defaults)
function __planShowPaymentPicker(planKey, amount) {
  const providers = [
    { id:'wave',   name:'Wave',          icon:'🌊', note:'Paiement instantané CI/SN' },
    { id:'orange', name:'Orange Money',  icon:'🟠', note:'USSD *144*4*6*...' },
    { id:'moov',   name:'Moov Money',    icon:'🔵', note:'USSD *155*...' },
    { id:'mtn',    name:'MTN Mobile Money', icon:'🟡', note:'USSD *133*1*...' },
    { id:'paypal', name:'PayPal',        icon:'🅿️', note:'International' },
  ];
  const modal = document.createElement('div');
  modal.id = '__planPickerModal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:10000;display:flex;align-items:center;justify-content:center;padding:20px';
  modal.innerHTML = `
    <div style="background:var(--surface);border-radius:20px;padding:20px;max-width:400px;width:100%;max-height:90vh;overflow-y:auto">
      <div style="font-size:18px;font-weight:900;text-align:center;margin-bottom:6px">Paiement Plan ${planKey.toUpperCase()}</div>
      <div style="font-size:20px;color:var(--accent);text-align:center;margin-bottom:14px;font-weight:800">${fmt(amount)} ${sym()}</div>
      <div style="font-size:12px;color:var(--text-3);text-align:center;margin-bottom:14px">Choisissez un moyen de paiement et entrez votre numéro</div>
      ${providers.map(p => `
        <button class="btn btn-ghost" style="width:100%;padding:12px;margin-bottom:8px;border:2px solid var(--border);font-weight:700;display:flex;align-items:center;gap:12px;justify-content:flex-start" onclick="document.getElementById('__planPickerModal').remove();__planQuickPay('${p.id}','${planKey}',${amount})">
          <span style="font-size:22px">${p.icon}</span>
          <div style="flex:1;text-align:left">
            <div style="font-size:14px">${p.name}</div>
            <div style="font-size:10px;color:var(--text-3);font-weight:500">${p.note}</div>
          </div>
        </button>
      `).join('')}
      <div style="display:flex;gap:8px;margin-top:8px">
        <button class="btn btn-ghost" style="flex:1;padding:10px;font-size:12px" onclick="document.getElementById('__planPickerModal').remove();nav('payments-setup')">⚙️ Configurer</button>
        <button class="btn btn-ghost" style="flex:1;padding:10px;font-size:12px;color:var(--text-3)" onclick="document.getElementById('__planPickerModal').remove()">Annuler</button>
      </div>
    </div>
  `;
  document.body.appendChild(modal);
}

// Demande le numéro puis initie le paiement
function __planQuickPay(providerId, planKey, amount) {
  const phone = prompt(`Votre numéro ${providerId === 'paypal' ? 'email PayPal' : 'Mobile Money'} :`, '');
  if (!phone) return;
  // Enregistre la méthode (pour prochains paiements)
  S.paymentMethods = S.paymentMethods || [];
  const existing = S.paymentMethods.find(m => m.provider === providerId);
  if (existing) {
    existing.phone = phone;
    existing.email = phone;
    existing.active = true;
  } else {
    const LBL = { wave:'Wave', orange:'Orange Money', moov:'Moov Money', mtn:'MTN Mobile Money', paypal:'PayPal' };
    S.paymentMethods.push({
      provider: providerId, name: LBL[providerId]||providerId,
      phone: phone, email: phone, active: true,
      configuredAt: new Date().toISOString(),
    });
  }
  localStorage.setItem('stockr_payments', JSON.stringify(S.paymentMethods));
  __planProcessPayment(providerId, planKey, amount);
}

// Traite un paiement et demande confirmation avant d'activer le plan
async function __planProcessPayment(providerId, planKey, amount) {
  const description = `BARO Plan ${planKey.toUpperCase()} — ${S.subscription.billing||'monthly'}`;
  const res = await payWithProvider(providerId, amount, description);
  if (!res.success) return;

  // Pour mobile money / PayPal : confirmation manuelle requise
  if (res.pending || ['wave','orange','moov','mtn','paypal'].includes(providerId)) {
    setTimeout(() => __planShowConfirmModal(planKey, amount, providerId), 1200);
    return;
  }
  // Pour PaymentRequest W3C (gpay/applepay/card) : activation immédiate
  _doActivatePlan(planKey, { trial: false, paid: true });
}

// Modal de confirmation post-paiement (mobile money / PayPal)
function __planShowConfirmModal(planKey, amount, providerId) {
  const LBL = { wave:'Wave', orange:'Orange Money', moov:'Moov Money', mtn:'MTN Mobile Money', paypal:'PayPal', lien:'Paiement en ligne' };
  const isLink = providerId === 'lien';
  const modal = document.createElement('div');
  modal.id = '__planConfirmPayModal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:10000;display:flex;align-items:center;justify-content:center;padding:20px';
  modal.innerHTML = `
    <div style="background:var(--surface);border-radius:20px;padding:24px;max-width:420px;width:100%">
      <div style="text-align:center;margin-bottom:18px">
        <div style="width:64px;height:64px;border-radius:50%;background:linear-gradient(135deg,#10B981,#059669);display:inline-flex;align-items:center;justify-content:center;font-size:32px;margin-bottom:10px">💳</div>
        <div style="font-size:18px;font-weight:900">Avez-vous complété le paiement ?</div>
        <div style="font-size:13px;color:var(--text-3);margin-top:6px">${LBL[providerId]||providerId} · ${fmt(amount)} ${sym()}</div>
      </div>
      <div style="background:var(--bg);border-radius:10px;padding:12px;margin-bottom:14px;font-size:12px;color:var(--text-2);line-height:1.5">
        <strong>⚠️ Important :</strong> ${isLink ? 'Termine le paiement sur la page ouverte. Si elle te redirige vers l\'app, le plan s\'active automatiquement. Sinon clique "Oui" une fois payé.' : 'Ne cliquez sur "Oui" que si le paiement a bien été débité sur votre ' + (providerId === 'paypal' ? 'PayPal' : 'Mobile Money') + '. Vous recevrez un SMS de confirmation.'}
      </div>
      <button class="btn btn-primary" style="width:100%;padding:14px;font-size:15px;font-weight:800;margin-bottom:8px" onclick="document.getElementById('__planConfirmPayModal').remove();_doActivatePlan('${planKey}', { trial:false, paid:true });logActivity('payment','Plan ${planKey} payé via ${providerId} — ${amount} FCFA')">
        ✅ Oui, paiement effectué
      </button>
      <button class="btn btn-ghost" style="width:100%;padding:12px;font-size:13px;color:var(--danger);border:1px solid var(--danger)" onclick="document.getElementById('__planConfirmPayModal').remove();showToast('Paiement annulé — réessayez','info')">
        ❌ Non, paiement échoué
      </button>
    </div>
  `;
  document.body.appendChild(modal);
}
