// ── BILAN FINANCIER PDF — rapport pro signé ───────────────────
function generateBilanReportPDF() {
  if (typeof window.jspdf === 'undefined') { showToast('jsPDF indisponible — réessayez en ligne', 'error'); return; }
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit:'mm', format:'a4' });
  const biz  = S.session?.business || S.session?.name || 'Mon Commerce';
  const date = new Date().toLocaleDateString('fr-FR', { day:'numeric', month:'long', year:'numeric' });
  const BRAND = [30,27,128]; // #1E1B80

  // ── Données (alignées sur la vue Bilan) ──
  const filtered  = salesForPeriod();
  const totalCA   = filtered.reduce((s,v)=>s+(v.total||0),0);
  const totalProfit = filtered.reduce((s,v)=>s+(v.profit||0),0);
  const avgMargin = totalCA > 0 ? Math.round((totalProfit/totalCA)*100) : 0;
  const nbVentes  = filtered.length;
  const panier    = nbVentes ? Math.round(totalCA/nbVentes) : 0;
  // Dépenses de la période → bénéfice NET réel (aligné sur la carte 💸 du Bilan)
  const exps      = expensesForPeriod();
  const totalExp  = exps.reduce((s,e)=>s+(e.amount||0),0);
  const netProfit = totalProfit - totalExp;
  const perLabel  = { today:"Aujourd'hui", '7d':'7 derniers jours', '30d':'30 derniers jours', all:'Depuis le début' }[S.period] || 'Global';

  // Comparaison période précédente
  let compare = null;
  if (S.period !== 'all') {
    const days = S.period==='today'?1:S.period==='7d'?7:30;
    const now=Date.now(), MS=86400000;
    const curStart=now-days*MS, prevStart=now-2*days*MS;
    const prevCA=(S.sales||[]).filter(s=>{const t=new Date(s.date).getTime();return t>=prevStart&&t<curStart;}).reduce((x,s)=>x+(s.total||0),0);
    if (!(prevCA===0 && totalCA===0)) {
      const pct = prevCA>0?Math.round(((totalCA-prevCA)/prevCA)*100):(totalCA>0?100:0);
      compare = { pct, label: S.period==='today'?'hier':S.period==='7d'?'7j préc.':'30j préc.' };
    }
  }

  // Série pour le graphe (par mois si "all", sinon par jour)
  const series = (() => {
    if (S.period === 'all') {
      const m = {};
      filtered.forEach(s => { const d=new Date(s.date); const k=d.toLocaleDateString('fr-FR',{month:'short',year:'2-digit'}); m[k]=(m[k]||0)+s.total; });
      const e = Object.entries(m).slice(-12);
      return e.map(([label,value])=>({label, value:Math.round(value)}));
    }
    const days = S.period==='today'?1:S.period==='7d'?7:30;
    const arr=[]; const now=new Date();
    for (let i=days-1;i>=0;i--) {
      const d=new Date(now); d.setDate(d.getDate()-i); const ds=d.toDateString();
      const v=filtered.filter(s=>new Date(s.date).toDateString()===ds).reduce((x,s)=>x+s.total,0);
      arr.push({ label:d.toLocaleDateString('fr-FR',{day:'2-digit',month:'2-digit'}), value:Math.round(v) });
    }
    return arr;
  })();

  // Répartition par catégorie (pie)
  const catColors = [[79,70,229],[124,58,237],[5,150,105],[234,88,12],[8,145,178],[220,38,38]];
  const _catByName = new Map();
  for (const p of (S.products || [])) if (p && p.name && !_catByName.has(p.name)) _catByName.set(p.name, p.category);
  for (const a of (S.articles || [])) if (a && a.name) _catByName.set(a.name, a.category);
  const catOf = name => _catByName.get(name) || 'Autres';
  const cmap={}; filtered.forEach(s=>{ const c=catOf(s.productName); cmap[c]=(cmap[c]||0)+(s.total||0); });
  const catData = Object.entries(cmap).map(([label,value])=>({label,value})).sort((a,b)=>b.value-a.value).slice(0,6)
    .map((d,i)=>({ ...d, color:catColors[i%catColors.length] }));

  // Top produits
  const stats={}; filtered.forEach(s=>{ if(!stats[s.productName])stats[s.productName]={qty:0,rev:0,profit:0}; stats[s.productName].qty+=s.qty; stats[s.productName].rev+=s.total; stats[s.productName].profit+=(s.profit||0); });
  const top = Object.entries(stats).sort((a,b)=>b[1].rev-a[1].rev).slice(0,8);

  // ── En-tête ──
  doc.setFillColor(...BRAND); doc.rect(0,0,210,34,'F');
  doc.setTextColor(255,255,255); doc.setFontSize(21); doc.setFont('helvetica','bold');
  doc.text('BILAN FINANCIER', 16, 16);
  doc.setFontSize(10); doc.setFont('helvetica','normal');
  doc.text(`${biz}  ·  ${perLabel}`, 16, 24);
  doc.setFontSize(8); doc.setTextColor(200,200,235);
  doc.text(`Édité le ${date}`, 16, 30);
  doc.setFontSize(13); doc.setFont('helvetica','bold'); doc.setTextColor(255,255,255);
  doc.text('BARO', 194, 16, { align:'right' });

  // ── KPI cards (4) ──
  let y = 42;
  const kpis = [
    { l:"Chiffre d'affaires", v:`${fmt(totalCA)} ${sym()}`, c:BRAND },
    { l:'Bénéfice net',       v:`${netProfit<0?'−':''}${fmt(Math.abs(netProfit))} ${sym()}`, c: netProfit>=0?[5,150,105]:[220,38,38] },
    { l:'Marge moyenne',      v:`${avgMargin}%`, c: avgMargin>=20?[5,150,105]:avgMargin>=0?[180,83,9]:[220,38,38] },
    { l:'Panier moyen',       v:`${fmt(panier)} ${sym()}`, c:[124,58,237] },
  ];
  const cardW = 42, gap = 3.33;
  kpis.forEach((k,i) => {
    const x = 16 + i*(cardW+gap);
    doc.setFillColor(249,250,251); doc.setDrawColor(230,231,235); doc.setLineWidth(0.3);
    doc.roundedRect(x, y, cardW, 22, 2, 2, 'FD');
    doc.setFillColor(...k.c); doc.rect(x, y, 1.4, 22, 'F');
    doc.setFontSize(7); doc.setTextColor(110,110,120); doc.setFont('helvetica','normal');
    doc.text(k.l.toUpperCase(), x+4, y+6);
    doc.setFontSize(11.5); doc.setTextColor(...k.c); doc.setFont('helvetica','bold');
    doc.text(String(k.v), x+4, y+15, { maxWidth: cardW-6 });
  });
  y += 28;

  // Ligne info : nb ventes + comparaison
  doc.setFontSize(9); doc.setFont('helvetica','normal'); doc.setTextColor(60,60,60);
  let info = `${nbVentes} vente${nbVentes>1?'s':''} sur la période`;
  if (totalExp > 0) info += `  ·  bénéfice brut ${fmt(totalProfit)} ${sym()}  −  ${exps.length} dépense${exps.length>1?'s':''} ${fmt(totalExp)} ${sym()}`;
  doc.text(info, 16, y);
  if (compare) {
    const up = compare.pct>=0;
    doc.setTextColor(...(up?[5,150,105]:[220,38,38])); doc.setFont('helvetica','bold');
    doc.text(`${up?'▲':'▼'} ${Math.abs(compare.pct)}% vs ${compare.label}`, 194, y, { align:'right' });
  }
  y += 6;

  // ── Graphe d'évolution du CA ──
  if (series.some(s=>s.value>0)) {
    _pdfBarChart(doc, { data:series, x:16, y, w:178, h:52, title:'Évolution du chiffre d\'affaires', color:BRAND, maxLabel: series.length<=14?series.length:0 });
  } else {
    doc.setFontSize(9); doc.setTextColor(150,150,150);
    doc.text('Aucune vente sur la période sélectionnée.', 16, y+10);
  }
  y += 60;

  // ── Colonne gauche : pie catégories · Colonne droite : top produits ──
  const colY = y;
  if (catData.length) {
    _pdfPieChart(doc, { data:catData, cx:48, cy:colY+24, r:20, title:'Répartition du CA par catégorie' });
  }
  // Top produits (droite)
  doc.setFontSize(10); doc.setFont('helvetica','bold'); doc.setTextColor(30,30,30);
  doc.text('Top produits', 110, colY);
  let ty = colY+7;
  doc.setFillColor(...BRAND); doc.rect(110, ty-5, 84, 8, 'F');
  doc.setTextColor(255,255,255); doc.setFontSize(8); doc.setFont('helvetica','bold');
  doc.text('PRODUIT', 113, ty); doc.text('QTÉ', 165, ty, {align:'center'}); doc.text('CA', 191, ty, {align:'right'});
  ty += 7;
  doc.setFont('helvetica','normal'); doc.setTextColor(40,40,40); doc.setFontSize(8);
  if (top.length === 0) { doc.setTextColor(150,150,150); doc.text('—', 113, ty); }
  top.forEach(([name,st],i)=>{
    if (i%2) { doc.setFillColor(249,250,251); doc.rect(110, ty-4, 84, 7, 'F'); }
    doc.setTextColor(40,40,40); doc.text(String(name).slice(0,26), 113, ty);
    doc.text(fmtQty(st.qty), 165, ty, {align:'center'});
    doc.setFont('helvetica','bold'); doc.text(`${fmt(st.rev)}`, 191, ty, {align:'right'});
    doc.setFont('helvetica','normal');
    ty += 7;
  });

  // ── Bloc signature / arrêté ──
  let sy = Math.max(colY + 60, ty + 8, 232);
  if (sy > 250) sy = 250;
  doc.setDrawColor(220,220,225); doc.setLineWidth(0.3); doc.line(16, sy-4, 194, sy-4);
  doc.setFontSize(9); doc.setFont('helvetica','normal'); doc.setTextColor(50,50,50);
  const arrete = totalExp > 0
    ? `Arrêté le présent bilan à un chiffre d'affaires de ${fmt(totalCA)} ${sym()}, un bénéfice brut de ${fmt(totalProfit)} ${sym()} et ${fmt(totalExp)} ${sym()} de dépenses, soit un bénéfice net de ${netProfit<0?'−':''}${fmt(Math.abs(netProfit))} ${sym()} (marge ventes ${avgMargin}%).`
    : `Arrêté le présent bilan à un chiffre d'affaires de ${fmt(totalCA)} ${sym()} pour un bénéfice net de ${fmt(totalProfit)} ${sym()} (marge ${avgMargin}%).`;
  doc.text(doc.splitTextToSize(arrete, 120), 16, sy+2);
  doc.setFontSize(9);
  doc.text(`Fait à ${(S.session?.city||'________________')}, le ${date}.`, 16, sy+16);
  // Cadre cachet & signature (droite)
  doc.setDrawColor(200,200,205); doc.roundedRect(134, sy-2, 60, 28, 2, 2, 'S');
  doc.setFontSize(7.5); doc.setTextColor(130,130,135);
  doc.text('Cachet & signature', 137, sy+3);
  doc.setFontSize(9); doc.setTextColor(40,40,40); doc.setFont('helvetica','bold');
  doc.text(String(biz).slice(0,30), 137, sy+23);

  // ── Pied de page ──
  doc.setFontSize(7.5); doc.setFont('helvetica','normal'); doc.setTextColor(150,150,150);
  doc.text(`Document généré automatiquement par BARO · ${date} · non contractuel`, 105, 290, { align:'center' });

  doc.save(`bilan_${S.period}_${new Date().toISOString().slice(0,10)}.pdf`);
  logActivity('export', `Bilan PDF exporté (${perLabel})`);
  showToast('📄 Bilan PDF généré', 'success');
}

function updateMarginPreview() {
  const cost = parseFloat($('prod-cost')?.value) || 0;
  const price = parseFloat($('prod-price')?.value) || 0;
  const box = document.getElementById('margin-preview');
  const val = document.getElementById('margin-val');
  if (!box || !val) return;
  if (price > 0) {
    const pct = Math.round(((price - cost) / price) * 100);
    const profit = price - cost;
    val.innerHTML = `${pct}% · ${t('profitShort')} ${fmt(profit)} ${sym()}/u`;
    val.style.color = pct >= 20 ? 'var(--success)' : pct >= 0 ? 'var(--warning)' : 'var(--danger)';
    box.style.display = '';
  } else {
    box.style.display = 'none';
  }
}

// Mise à jour LIVE de la marge dans le form article revendeur, SANS render()
// → l'input garde son focus et le curseur reste à sa place pendant que l'user tape.
function updateArticleMarginPreview() {
  const box = document.getElementById('art-marge-preview');
  if (!box) return;
  const ha = parseFloat(S.form?.purchasePrice) || 0;
  const pv = parseFloat(S.form?.price) || 0;
  if (ha > 0 && pv > 0) {
    const margeFcfa = pv - ha;
    const margePct  = pv > 0 ? Math.round(((pv - ha) / pv) * 100) : 0;
    const fcfaColor = margeFcfa >= 0 ? 'var(--success)' : 'var(--danger)';
    const pctColor  = margePct >= 30 ? 'var(--success)' : margePct >= 15 ? 'var(--warning)' : 'var(--danger)';
    box.innerHTML = `<div style="padding:10px;background:var(--bg);border-radius:var(--r-sm);display:flex;justify-content:space-between;align-items:center;gap:8px">
      <div>
        <div style="font-size:10px;color:var(--text-3)">MARGE PAR UNITÉ</div>
        <div id="art-marge-fcfa" style="font-size:16px;font-weight:800;color:${fcfaColor}">${fmt(margeFcfa)} ${sym()}</div>
      </div>
      <div style="text-align:right">
        <div style="font-size:10px;color:var(--text-3)">MARGE %</div>
        <div id="art-marge-pct" style="font-size:16px;font-weight:800;color:${pctColor}">${margePct}%</div>
      </div>
    </div>`;
  } else {
    box.innerHTML = '<div style="font-size:11px;color:var(--text-3)">Renseignez les deux prix pour voir la marge</div>';
  }
}
if (typeof window !== 'undefined') window.updateArticleMarginPreview = updateArticleMarginPreview;

function toggleCart() {
  S.cartOpen = !S.cartOpen;
  render();
}

async function deleteProduct(id) {
  if (typeof hasPermission === 'function' && !hasPermission('products') && !hasPermission('all')) {
    if (typeof requirePermission === 'function') requirePermission('products');
    return;
  }
  const p = S.products.find(p => p.id === id);
  if (!p) return;
  if (!confirm(`Supprimer "${p.name}" ?`)) return;
  try {
    await api('DELETE', `/api/products/${id}`);
    S.products = S.products.filter(p => p.id !== id);
    if (typeof logAudit === 'function') logAudit('product', 'delete', { name: p.name, id });
    showToast(`"${p.name}" supprimé`);
    render();
  } catch(e) {
    showToast(e.message, 'error');
  }
}

async function saveEditProduct() {
  const nameEl  = $('prod-name');
  const priceEl = $('prod-price');
  if (!nameEl?.value.trim()) { showToast(t('nameRequired'), 'error'); return; }
  const p = S.products.find(p => p.id === S.editProductId);
  if (!p) return;
  const composition = [];
  document.querySelectorAll('.comp-input').forEach(row => {
    const artId = parseInt(row.dataset.id);
    const art   = S.articles.find(a => a.id === artId);
    const qtyEl = row.querySelector('.comp-qty');
    const rawQty = parseFloat(qtyEl?.value) || 0;
    if (rawQty > 0 && art) {
      const selUnit   = S.compUnits[artId] || art.unit;
      const converted = convertQty(rawQty, selUnit, art.unit);
      composition.push({ article_id: artId, quantity_used: converted });
    }
  });
  try {
    const costEl = $('prod-cost');
    const data = await api('PUT', `/api/products/${p.id}`, {
      name:           nameEl.value.trim(),
      purchase_price: parseFloat(costEl?.value) || 0,
      price:          parseFloat(priceEl?.value) || 0,
      composition,
    });
    p.name  = data.name;
    p.price = data.price;
    p.purchasePrice = data.purchase_price || 0;
    p.composition = (data.composition || []).map(c => ({ id: c.article.id, qty: c.quantity_used }));
    if (S.productForm?.image) p.image = S.productForm.image;
    else if (S.productForm?.imageCleared) p.image = '';
    S.productForm = null;
    try { localStorage.setItem('stockr_products', JSON.stringify(S.products)); } catch(_){}
    recalcAllMins();
    showToast(`"${p.name}" mis à jour`);
    nav('products');
  } catch(e) {
    showToast(e.message, 'error');
  }
}

function toggleAuthPwd(e) {
  if (e) { e.preventDefault(); e.stopPropagation(); }
  S.authShowPwd = !S.authShowPwd;
  // Zéro render() — DOM direct uniquement, les champs ne sont jamais vidés
  const pEl  = document.getElementById('auth-pwd');
  const p2El = document.getElementById('auth-pwd2');
  if (pEl)  pEl.classList.toggle('pwd-masked', !S.authShowPwd);
  if (p2El) p2El.classList.toggle('pwd-masked', !S.authShowPwd);
  document.querySelectorAll('.pwd-eye').forEach(btn => {
    btn.innerHTML = S.authShowPwd ? IC.eyeOff : IC.eye;
  });
}

// ── Cart actions ──────────────────────────────
function addToCart() {
  const sel   = $('sale-product');
  const qtyEl = $('sale-qty');
  if (!sel?.value) { showToast(t('chooseProduct'), 'error'); return; }
  const val = String(sel.value);
  // Handle both prefixed (prod_X / art_X / pack_X) and raw product id — gère aussi le mode revendeur
  let item = null;
  const sellable = bt_sellableItems();
  item = sellable.find(it => it.id === val) || sellable.find(it => String(it.productId||'') === val);
  if (!item && /^\d+$/.test(val)) {
    // backwards compat : pure numeric id means a product
    const product = S.products.find(p => p.id === parseInt(val));
    if (product) item = { id:'prod_'+product.id, productId:product.id, name:product.name, price:product.price, purchasePrice:product.purchasePrice||0, kind:'product' };
  }
  if (!item) return;
  // Quantités décimales autorisées (kg, mètres, litres…)
  const qty = Math.max(0.001, parseFloat(qtyEl?.value) || 1);
  const existing = S.cart.find(c => c.cartId === item.id);
  if (existing) { existing.qty += qty; }
  else {
    S.cart.push({
      cartId: item.id,
      kind: item.kind,
      productId: item.productId || null,
      articleId: item.articleId || null,
      productName: item.name,
      qty,
      unitPrice: item.price,
      unitCost: item.purchasePrice,
    });
  }
  showToast(`${item.name} ajouté au panier`);
  render();
}

function removeFromCart(idx) {
  S.cart.splice(idx, 1);
  render();
}

// ── Multi-cart (vente en lot) ─────────────────
function setSaleMode(mode) {
  S.saleMode = mode;
  render();
}
function toggleMultiCart(itemId) {
  if (!S.multiCart) S.multiCart = {};
  if (S.multiCart[itemId]) delete S.multiCart[itemId];
  else S.multiCart[itemId] = 1;
  render();
}
function updateMultiCartQty(itemId, delta) {
  if (!S.multiCart) S.multiCart = {};
  const sellable = bt_sellableItems();
  const it = sellable.find(i => i.id === itemId);
  const max = it ? it.stock : 9999;
  const current = S.multiCart[itemId] || 0;
  const raw = current + delta;
  if (raw <= 0) { delete S.multiCart[itemId]; }   // retire l'article à 0
  else { S.multiCart[itemId] = Math.min(max, raw); }
  haptic('tap');
  render();
}
function setMultiCartQty(itemId, val) {
  if (!S.multiCart) S.multiCart = {};
  const sellable = bt_sellableItems();
  const it = sellable.find(i => i.id === itemId);
  const max = it ? it.stock : 9999;
  const n = Math.max(1, Math.min(max, parseInt(val) || 1));
  S.multiCart[itemId] = n;
  render();
}
function clearMultiCart() {
  S.multiCart = {};
  render();
}
async function confirmMultiSale(opts = {}) {
  if (!S.multiCart || !Object.keys(S.multiCart).length) { showToast('Panier vide', 'error'); return; }
  if (!_checkPlanLimit('salesPerMonth', _salesThisMonth(), 'ventes ce mois')) return;
  const sellable = bt_sellableItems();
  // ── Résolution du client : nouveau client à la volée, ou choix existant
  //    (ids chaîne supportés, sélection mémorisée : survit aux re-renders des taps produits) ──
  let clientId = null;
  if (opts.clientId !== undefined) {
    clientId = opts.clientId;
  } else if (S.multiNewClient) {
    const nameEl  = $('multi-new-client-name');
    const phoneEl = $('multi-new-client-phone');
    const name  = ((nameEl && nameEl.value) ? nameEl.value : (S.multiNewClientName || '')).trim();
    const phone = ((phoneEl && phoneEl.value) ? phoneEl.value : (S.multiNewClientPhone || '')).trim();
    if (name) {
      const existing = S.clients.find(c => (c.name||'').toLowerCase() === name.toLowerCase());
      if (existing) { clientId = existing.id; }
      else {
        const nc = { id: Date.now(), name, phone, email: '', address: '', loyaltyPoints: 0, createdAt: new Date().toISOString() };
        S.clients.push(nc); _saveClients();
        clientId = nc.id;
      }
      S.multiNewClient = false; S.multiNewClientName = ''; S.multiNewClientPhone = '';
    }
  } else {
    const clientSel = $('multi-client');
    clientId = clientSel && clientSel.value ? (parseInt(clientSel.value) || clientSel.value) : (S.multiClientPick != null ? S.multiClientPick : null);
  }
  const client = clientId != null ? S.clients.find(c => String(c.id) === String(clientId)) : null;
  clientId = client ? client.id : null;
  const pmSel = $('multi-payment');
  const payMethod = opts.payMethod || (pmSel ? pmSel.value : 'cash');
  // Panier multi = un même cartId → groupé « Panier · N articles » dans l'historique
  const _multiCartId = Object.keys(S.multiCart).length > 1 ? 'cart_' + Date.now() : null;

  let total = 0, newSales = [];
  for (const [itemId, qty] of Object.entries(S.multiCart)) {
    const it = sellable.find(i => i.id === itemId);
    if (!it) continue;
    let lineTotal = it.price * qty;
    let lineProfit = (it.price - (it.purchasePrice||0)) * qty;
    let promoName = null, promoDiscount = 0;
    if (it.kind === 'product') {
      const promo = _getActivePromo(it.productId);
      if (promo) { promoDiscount = promo.discount; promoName = promo.name; const d = Math.round(lineTotal*promoDiscount/100); lineTotal -= d; lineProfit -= d; }
    }
    try {
      let saleData = null;
      if (it.kind === 'product') {
        try {
          const data = await api('POST', '/api/sales/', { product_id: it.productId, quantity: qty, client_id: clientId, client_name: client?.name || null });
          saleData = data.sale;
        } catch(e) { /* fallback offline */ }
      } else if (it.kind === 'article') {
        // Décrémente directement l'article
        const article = S.articles.find(a => a.id === it.articleId);
        if (article) {
          article.stock = Math.max(0, (article.stock||0) - qty);
          _saveArticles();
          try { await api('PUT', `/api/articles/${article.id}`, { stock: article.stock }); } catch(e) {}
          pushMovement(article.name, 'exit', qty, 'Vente directe');
        }
      } else if (it.kind === 'pack') {
        // Pack : vendre chaque produit du pack au prorata du pack
        const pack = S.packs.find(p => p.id === it.packId);
        if (pack) {
          for (const comp of (pack.items||[])) {
            try {
              await api('POST', '/api/sales/', { product_id: comp.productId, quantity: (comp.qty||1)*qty, client_id: clientId, client_name: client?.name || null });
            } catch(e) { /* fallback offline */ }
          }
          // Tracer la vente du pack
          pushMovement(pack.name, 'exit', qty, `Vente pack`);
        }
      }
      const __mm = (typeof getCurrentMember === 'function') ? getCurrentMember() : null;
      const newSale = {
        id: saleData?.id || Date.now() + Math.random(),
        cartId: _multiCartId,
        productId: it.productId || null,
        articleId: it.articleId || null,
        packId:    it.packId    || null,
        productName: it.name,
        qty,
        total: lineTotal,
        profit: lineProfit,
        date: saleData?.timestamp || new Date().toISOString(),
        clientId, clientName: client?.name || null,
        paymentMethod: payMethod, promoName, promoDiscount,
        kind: it.kind,
        memberId: __mm?.id || null, memberName: __mm?.name || null, locationId: S.currentLocation || null,
      };
      S.sales.unshift(newSale);
      newSales.push(newSale);
      total += lineTotal;
    } catch(e) { console.warn('sale error', e); }
  }
  localStorage.setItem('stockr_sales', JSON.stringify(S.sales));

  // Loyalty with tier multiplier
  if (S.loyaltyConfig?.enabled && clientId) {
    const cl = S.clients.find(c => String(c.id) === String(clientId));
    if (cl) {
      const tier = _getClientTier(cl);
      const mult = tier?.multiplier || 1;
      const pts = Math.floor(total * (S.loyaltyConfig.pointsPerFcfa||1) * mult);
      cl.loyaltyPoints = (cl.loyaltyPoints||0) + pts;
      _saveClients();
      const newTier = _getClientTier(cl);
      if (newTier && tier && newTier.id !== tier.id && newTier.min > tier.min) {
        showToast(`🎉 ${cl.name} → palier ${newTier.name} ${newTier.icon||''} !`, 'success');
      }
    }
  }
  if (payMethod !== 'cash') {
    S.paymentHistory.unshift({ id:Date.now(), provider:payMethod, amount:total, clientName:client?.name||'Client', date:new Date().toISOString() });
    localStorage.setItem('baro_payment_history', JSON.stringify(S.paymentHistory));
  }
  // Honnêteté : si aucune ligne n'a pu être vendue (article retiré de la
  // vitrine entre-temps, panier obsolète), ne pas annoncer un faux succès.
  if (!newSales.length) {
    showToast("Aucun article n'a pu être vendu — vérifiez le panier", 'error');
    render();
    return;
  }
  logActivity('sale', `Vente multi: ${newSales.length} article(s) — ${fmt(total)} ${sym()}`);
  showToast(`✅ ${newSales.length} article${newSales.length>1?'s':''} vendu${newSales.length>1?'s':''} — ${fmt(total)} ${sym()}`, 'success');
  S.multiCart = {};
  S.multiSearch = '';
  S.multiClientPick = null;
  showReceiptBanner(newSales, total, { provider: payMethod, clientId });
  render();
}

// ── VENTE RAPIDE depuis le stock/boutique (revendeur & mixte) ──
// Un article est vendable directement s'il a un prix de vente et du stock.
function _articleSellable(a) {
  const t = getBusinessType();
  return (t === 'reseller' || t === 'mixed') && (a && (a.price||0) > 0 && (a.stock||0) > 0);
}
function openQuickSell(articleId) {
  const a = S.articles.find(x => x.id === articleId);
  if (!a) return;
  if ((a.price||0) <= 0) { showToast('Ajoutez un prix de vente à cet article', 'info'); nav('detail',{selectedId:articleId}); return; }
  if ((a.stock||0) <= 0) { showToast('Stock épuisé pour ' + a.name, 'error'); return; }
  S._qs = { id: articleId, qty: 1, pay: 'cash', clientId: null };
  const existing = document.getElementById('qs-modal'); if (existing) existing.remove();
  const modal = document.createElement('div');
  modal.id = 'qs-modal';
  modal.className = 'qs-overlay';
  modal.onclick = (e) => { if (e.target === modal) closeQuickSell(); };
  modal.innerHTML = `<div class="qs-sheet"><div class="qs-inner"></div></div>`;
  document.body.appendChild(modal);
  _qsRender();
  if (typeof haptic === 'function') haptic('tap');
}
function closeQuickSell() { const m = document.getElementById('qs-modal'); if (m) m.remove(); S._qs = null; }
function _qsSetQty(d) {
  const qs = S._qs; if (!qs) return;
  const a = S.articles.find(x => x.id === qs.id); const max = a ? Math.max(1, Math.floor(a.stock)) : 1;
  qs.qty = Math.max(1, Math.min(max, (qs.qty||1) + d)); _qsRender();
}
function _qsSetQtyVal(v) {
  const qs = S._qs; if (!qs) return;
  const a = S.articles.find(x => x.id === qs.id); const max = a ? Math.max(1, Math.floor(a.stock)) : 1;
  qs.qty = Math.max(1, Math.min(max, parseInt(v)||1)); _qsRender();
}
function _qsSetPay(p) { if (S._qs) { S._qs.pay = p; _qsRender(); } }
function _qsSetClient(v) { if (S._qs) { S._qs.clientId = v ? parseInt(v) : null; _qsRender(); } }
// Options de paiement pour la vente : Espèces + vos méthodes ACTIVES configurées.
// Repli sur le mobile money courant si rien n'est encore configuré.
function _salePayChips() {
  const labels = { wave:'Wave', orange:'Orange', moov:'Moov', mtn:'MTN', paypal:'PayPal', visa:'Carte', gpay:'Google Pay', applepay:'Apple Pay', stripe:'Carte' };
  const active = (S.paymentMethods || []).filter(m => m.active);
  const chips = [['cash','💵 Espèces']];
  if (active.length) active.forEach(m => chips.push([m.provider, labels[m.provider] || m.name]));
  else [['wave','Wave'],['orange','Orange'],['moov','Moov'],['mtn','MTN']].forEach(c => chips.push(c));
  return chips;
}
function _qsBody() {
  const qs = S._qs; if (!qs) return '';
  const a = S.articles.find(x => x.id === qs.id); if (!a) return '';
  const price = a.price||0, cost = a.purchasePrice||0;
  const total = price * qs.qty, profit = (price - cost) * qs.qty;
  const max = Math.max(1, Math.floor(a.stock));
  const pms = _salePayChips();
  const clientsOpts = (S.clients||[]).map(c=>`<option value="${c.id}" ${qString(s.clientId)===String(c.id)?'selected':''}>${(c.name||'Client').replace(/"/g,'&quot;')}</option>`).join('');
  return `
    <div class="qs-head">
      ${itemAvatar(a, 'flex:0 0 auto')}
      <div style="flex:1;min-width:0">
        <div class="qs-title">${a.name}</div>
        <div class="qs-sub">${fmtQty(a.stock)} ${a.unit||'pcs'} · ${fmt(price)} ${sym()}/u${cost>0?` · marge +${Math.round(((price-cost)/price)*100)}%`:''}</div>
      </div>
      <button class="qs-x" onclick="closeQuickSell()" aria-label="Fermer">✕</button>
    </div>
    <div class="qs-label">Quantité</div>
    <div class="qs-qtyrow">
      <button class="qs-step" onclick="_qsSetQty(-1)">−</button>
      <input class="qs-qty" type="number" inputmode="numeric" value="${qs.qty}" min="1" max="${max}" onchange="_qsSetQtyVal(this.value)">
      <button class="qs-step" onclick="_qsSetQty(1)">+</button>
      <div class="qs-max">/ ${max} dispo</div>
    </div>
    <div class="qs-label">Paiement</div>
    <div class="qs-pms">
      ${pms.map(([k,l])=>`<button class="qs-pm ${qs.pay===k?'active':''}" onclick="_qsSetPay('${k}')">${l}</button>`).join('')}
    </div>
    ${(S.clients||[]).length ? `
    <div class="qs-label">Client (optionnel)</div>
    <select class="input qs-client" onchange="_qsSetClient(this.value)"><option value="">— Aucun —</option>${clientsOpts}</select>` : ''}
    <div class="qs-totals">
      <div class="qs-trow"><span>Total</span><b>${fmt(total)} ${sym()}</b></div>
      ${cost>0?`<div class="qs-trow qs-profit"><span>Bénéfice</span><b>+${fmt(profit)} ${sym()}</b></div>`:''}
    </div>
    <button class="btn btn-primary qs-confirm" onclick="quickSellConfirm()">✓ Confirmer la vente</button>
  `;
}
function _qsRender() {
  const m = document.getElementById('qs-modal'); if (!m || !S._qs) return;
  const inner = m.querySelector('.qs-inner'); if (inner) inner.innerHTML = _qsBody();
}
async function quickSellConfirm() {
  const qs = S._qs; if (!qs) return;
  const a = S.articles.find(x => x.id === qs.id); if (!a) { closeQuickSell(); return; }
  if ((a.stock||0) < qs.qty) { showToast('Stock insuffisant', 'error'); return; }
  const payMethod = qs.pay || 'cash';
  const clientId = qs.clientId || null;
  S.multiCart = { ['art_'+qs.id]: qs.qty };
  closeQuickSell();
  await confirmMultiSale({ clientId, payMethod });
}

// ── Prestation / service : encaisser sans stock (coiffure, couture, réparation…) ──
function _svcPreset(i) {
  const f = (window._svcFreq || [])[i];
  if (!f) return;
  S.serviceDesc = f.d;
  S.serviceAmount = String(f.a || '');
  render();
}
function confirmServiceSale() {
  const desc   = ((($('svc-desc')   || {}).value) || S.serviceDesc   || '').trim();
  const amount = Math.max(0, parseFloat(((($('svc-amount') || {}).value) || S.serviceAmount)) || 0);
  const cost   = Math.max(0, parseFloat(((($('svc-cost')   || {}).value) || S.serviceCost))   || 0);
  if (!desc)       { showToast('Décrivez la prestation', 'error'); return; }
  if (amount <= 0) { showToast('Entrez le montant encaissé', 'error'); return; }
  if (!_checkPlanLimit('salesPerMonth', _salesThisMonth(), 'ventes ce mois')) return;
  const { clientId, clientName } = _resolveClientForSale();
  const pmSel = $('sale-payment');
  const payMethod = pmSel ? pmSel.value : 'cash';
  const __m = (typeof getCurrentMember === 'function') ? getCurrentMember() : null;
  const sale = {
    id: Date.now(), kind: 'service',
    productId: null, articleId: null,
    productName: desc, qty: 1,
    total: amount, profit: Math.max(0, amount - cost),
    date: new Date().toISOString(), paymentMethod: payMethod,
    clientId, clientName,
    memberId: __m?.id || null, memberName: __m?.name || null, locationId: S.currentLocation || null,
  };
  S.sales.unshift(sale);
  localStorage.setItem('stockr_sales', JSON.stringify(S.sales));
  // Fidélité (même règle que les autres ventes)
  if (S.loyaltyConfig?.enabled && clientId) {
    const cl = S.clients.find(c => String(c.id) === String(clientId));
    if (cl) {
      const tier = _getClientTier(cl);
      const pts = Math.floor(amount * (S.loyaltyConfig.pointsPerFcfa || 1) * (tier?.multiplier || 1));
      cl.loyaltyPoints = (cl.loyaltyPoints || 0) + pts;
      _saveClients();
    }
  }
  if (payMethod !== 'cash') {
    S.paymentHistory.unshift({ id: Date.now(), provider: payMethod, amount, clientName: clientName || 'Client', date: new Date().toISOString() });
    localStorage.setItem('baro_payment_history', JSON.stringify(S.paymentHistory));
  }
  logActivity('sale', `Prestation : ${desc} — ${fmt(amount)} ${sym()}`);
  showToast(`✅ Prestation encaissée — ${fmt(amount)} ${sym()}`, 'success');
  S.serviceDesc = ''; S.serviceAmount = ''; S.serviceCost = '';
  showReceiptBanner([sale], amount, { provider: payMethod, clientId });
  render();
}

async function confirmCart() {
  if (!S.cart.length) { showToast(t('emptyCartMsg'), 'error'); return; }
  // Limite de ventes/mois selon le plan (free 100, starter 2000, pro/ent illimité)
  if (!_checkPlanLimit('salesPerMonth', _salesThisMonth(), 'ventes ce mois')) return;
  const { clientId, clientName: resolvedClientName } = _resolveClientForSale();
  const client = clientId ? S.clients.find(c => String(c.id) === String(clientId)) : null;
  const __m = (typeof getCurrentMember === 'function') ? getCurrentMember() : null;
  const pmSel = $('sale-payment');
  const payMethod = pmSel ? pmSel.value : 'cash';
  try {
    const cartId = 'cart_' + Date.now();
    let total = 0, count = 0, newSales = [];
    for (const item of S.cart) {
      // ── Article stock direct (revendeur) : destockage local, pas d'API ──
      if (item.kind === 'article' && item.articleId) {
        const art = S.articles.find(a => a.id === item.articleId);
        if (art) art.stock = Math.round(((art.stock||0) - item.qty) * 1000) / 1000;
        const lineTotal  = (item.unitPrice||0) * item.qty;
        const lineProfit = ((item.unitPrice||0) - (item.unitCost || 0)) * item.qty;
        total += lineTotal; count += item.qty;
        const newSale = { id: Date.now() + Math.random(), cartId, productId: null, articleId: item.articleId, productName: item.productName, qty: item.qty, total: lineTotal, profit: lineProfit, date: new Date().toISOString(), clientId, clientName: resolvedClientName || client?.name || null, paymentMethod: payMethod };
        S.sales.unshift(newSale); newSales.push(newSale);
        try { _saveArticles(); } catch(_){}
        continue;
      }
      // ── Pack : destockage local des composants, pas d'API ──
      if (item.kind === 'pack' && item.packId) {
        const pack = S.packs?.find(pk => pk.id === item.packId);
        if (pack?.items?.length) {
          for (const pi of pack.items) {
            const p = S.products.find(pr => pr.id === pi.productId);
            if (p?.composition) {
              for (const c of p.composition) {
                const a = S.articles.find(x => x.id === c.id);
                if (a) a.stock = Math.round(((a.stock||0) - (c.qty||0) * (pi.qty||1) * item.qty) * 1000) / 1000;
              }
            }
          }
        }
        const lineTotal  = (item.unitPrice||0) * item.qty;
        const lineProfit = ((item.unitPrice||0) - (item.unitCost || 0)) * item.qty;
        total += lineTotal; count += item.qty;
        const newSale = { id: Date.now() + Math.random(), cartId, productId: null, packId: item.packId, productName: item.productName, qty: item.qty, total: lineTotal, profit: lineProfit, date: new Date().toISOString(), clientId, clientName: resolvedClientName || client?.name || null, paymentMethod: payMethod };
        S.sales.unshift(newSale); newSales.push(newSale);
        try { _saveArticles(); } catch(_){}
        continue;
      }
      // ── Produit classique : tente l'API, fallback local si échec (offline ou produit non-sync) ──
      let data = null;
      try {
        data = await api('POST', '/api/sales/', { product_id: item.productId, quantity: item.qty, client_id: clientId, client_name: client?.name || null });
      } catch(apiErr) {
        data = null; // fallback géré juste après
      }
      const product = S.products.find(p => p.id === item.productId);
      let lineTotal  = (item.unitPrice || product?.price || 0) * item.qty;
      let lineProfit = ((item.unitPrice || product?.price || 0) - (item.unitCost || product?.purchasePrice || 0)) * item.qty;
      // Apply promo discount
      const promo = _getActivePromo(item.productId);
      let promoName = null, promoDiscount = 0;
      if (promo) {
        promoDiscount = promo.discount;
        promoName = promo.name;
        const discount = Math.round(lineTotal * promoDiscount / 100);
        lineTotal -= discount;
        lineProfit -= discount;
      }
      // Si pas de data API → destockage local des composants
      if (!data && product?.composition) {
        for (const c of product.composition) {
          const a = S.articles.find(x => x.id === c.id);
          if (a) a.stock = Math.round(((a.stock||0) - (c.qty||0) * item.qty) * 1000) / 1000;
        }
      }
      total += lineTotal;
      count += item.qty;
      const newSale = data?.sale
        ? { id: data.sale.id, cartId, productId: data.sale.product_id, productName: data.sale.product_name, qty: data.sale.quantity, total: lineTotal, profit: lineProfit, date: data.sale.timestamp, clientId, clientName: resolvedClientName || client?.name || null, paymentMethod: payMethod, promoName, promoDiscount }
        : { id: Date.now() + Math.random(), cartId, productId: item.productId, productName: item.productName || product?.name, qty: item.qty, total: lineTotal, profit: lineProfit, date: new Date().toISOString(), clientId, clientName: resolvedClientName || client?.name || null, paymentMethod: payMethod, promoName, promoDiscount };
      S.sales.unshift(newSale);
      newSales.push(newSale);
      try { _saveArticles(); } catch(_){}
    }
    // Attribution au vendeur connecté (sinon admin) — pour "Ventes par vendeur" & stats équipe
    newSales.forEach(s => { s.memberId = __m?.id || null; s.memberName = __m?.name || null; s.locationId = S.currentLocation || null; });
    // Loyalty points (with tier multiplier)
    if (S.loyaltyConfig?.enabled && clientId) {
      const cl = S.clients.find(c => c.id === clientId);
      if (cl) {
        const tier = _getClientTier(cl);
        const mult = tier?.multiplier || 1;
        const pts = Math.floor(total * (S.loyaltyConfig.pointsPerFcfa || 1) * mult);
        cl.loyaltyPoints = (cl.loyaltyPoints || 0) + pts;
        _saveClients();
        const newTier = _getClientTier(cl);
        if (newTier && tier && newTier.id !== tier.id && newTier.min > tier.min) {
          showToast(`🎉 ${cl.name} a atteint le palier ${newTier.name} ${newTier.icon||''} !`, 'success');
        }
      }
    }
    // Payment history
    if (payMethod !== 'cash') {
      S.paymentHistory.unshift({ id:Date.now(), provider:payMethod, amount:total, clientName:client?.name||'Client', date:new Date().toISOString() });
      localStorage.setItem('baro_payment_history', JSON.stringify(S.paymentHistory));
    }
    S.cart = [];
    S.saleClientPick = null; S.saleNewClient = false; S.saleNewClientName = ''; S.saleNewClientPhone = '';
    showToast(`${count} ${t('unitsSold')} — ${fmt(total)} ${sym()}`);
    showReceiptBanner(newSales, total);
    // Persist local state (articles/sales) quoi qu'il arrive
    try {
      _saveArticles();
      localStorage.setItem('baro_sales',    JSON.stringify(S.sales));
      _saveArticles();
      localStorage.setItem('stockr_sales',    JSON.stringify(S.sales));
    } catch(_) {}
    // Recharger les articles depuis l'API si possible (silencieux en cas d'échec offline)
    try {
      const arts = await api('GET', '/api/articles/');
      if (Array.isArray(arts) && arts.length) {
        // Préserver les extras boutique (photo, photos sup., variantes, avis) que
        // l'API ne stocke pas — sinon ils disparaissent après une vente.
        const __ex = {}; (S.articles||[]).forEach(x => { if (x && x.id != null) __ex[x.id] = { image:x.image, images:x.images, variants:x.variants, reviews:x.reviews }; });
        S.articles = arts.map(articleFromAPI).map(a => {
          const e = __ex[a.id]; if (e) {
            if (!a.image && e.image) a.image = e.image;
            if (Array.isArray(e.images)  && e.images.length)  a.images  = e.images;
            if (Array.isArray(e.variants) && e.variants.length) a.variants = e.variants;
            if (Array.isArray(e.reviews) && e.reviews.length) a.reviews = e.reviews;
          }
          return a;
        });
        try { _saveArticles(); } catch(_){}
      }
    } catch(_) { /* offline : garder l'état local */ }
    try { recalcAllMins(); } catch(_) {}
    render();
  } catch(e) {
    // Traduire les erreurs anglaises du backend
    let msg = e?.message || 'Erreur lors de la vente';
    msg = msg
      .replace(/Product not found/gi, 'Produit introuvable')
      .replace(/Insufficient stock/gi, 'Stock insuffisant')
      .replace(/Network error/gi, 'Erreur réseau')
      .replace(/Unauthorized/gi, 'Session expirée');
    showToast(msg, 'error');
  }
}

// ── PACKS MANAGEMENT ──────────────────────────
function setProductsTab(tab) {
  S.productsTab = tab;
  render();
}
function resetPackForm() {
  S.packForm = { name:'', description:'', items:[], price:0, discount:0, autoPrice:true, active:true };
  S.editPackId = null;
}
function addPackComponent(productId) {
  if (!S.packForm) resetPackForm();
  productId = parseInt(productId);
  if (!productId) return;
  const existing = S.packForm.items.find(it => it.productId === productId);
  if (existing) { existing.qty = (existing.qty||1) + 1; }
  else { S.packForm.items.push({ productId, qty: 1 }); }
  render();
}
function removePackComponent(productId) {
  if (!S.packForm) return;
  productId = parseInt(productId);
  S.packForm.items = S.packForm.items.filter(it => it.productId !== productId);
  render();
}
function updatePackComponentQty(productId, qty) {
  productId = parseInt(productId);
  const q = Math.max(1, parseInt(qty) || 1);
  const it = S.packForm.items.find(i => i.productId === productId);
  if (it) { it.qty = q; render(); }
}
function updatePackFormField(key, val) {
  if (!S.packForm) resetPackForm();
  if (key === 'autoPrice') S.packForm.autoPrice = !!val;
  else if (key === 'active') S.packForm.active = !!val;
  else if (key === 'discount') S.packForm.discount = Math.max(0, Math.min(100, parseFloat(val)||0));
  else if (key === 'price') S.packForm.price = Math.max(0, parseFloat(val)||0);
  else S.packForm[key] = val;
}
function savePack() {
  const f = S.packForm;
  if (!f?.name?.trim()) { showToast('Nom requis', 'error'); return; }
  if (!f.items?.length) { showToast('Ajoutez au moins un produit', 'error'); return; }
  if (!Array.isArray(S.packs)) S.packs = [];
  if (S.editPackId) {
    const idx = S.packs.findIndex(p => p.id === S.editPackId);
    if (idx >= 0) {
      S.packs[idx] = { ...S.packs[idx], ...f, id: S.editPackId, updatedAt: new Date().toISOString() };
    }
    showToast(`Pack "${f.name}" mis à jour`);
  } else {
    S.packs.unshift({ id: Date.now(), ...f, createdAt: new Date().toISOString() });
    showToast(`Pack "${f.name}" créé`);
    logActivity('pack', `Création pack "${f.name}"`);
  }
  persistPacks();
  resetPackForm();
  S.view = 'products';
  S.productsTab = 'packs';
  render();
}
function editPack(id) {
  const pk = S.packs.find(p => p.id === id);
  if (!pk) return;
  S.editPackId = id;
  S.packForm = {
    name: pk.name || '',
    description: pk.description || '',
    items: (pk.items||[]).map(it => ({ ...it })),
    price: pk.price || 0,
    discount: pk.discount || 0,
    autoPrice: pk.autoPrice !== false,
    active: pk.active !== false,
  };
  S.view = 'pack-form';
  render();
}
function deletePack(id) {
  const pk = S.packs.find(p => p.id === id);
  if (!pk) return;
  if (!confirm(`Supprimer le pack "${pk.name}" ?`)) return;
  S.packs = S.packs.filter(p => p.id !== id);
  persistPacks();
  showToast(`Pack "${pk.name}" supprimé`);
  render();
}
function togglePackActive(id) {
  const pk = S.packs.find(p => p.id === id);
  if (!pk) return;
  // active:undefined = actif implicite → le 1er tap doit bien DÉSACTIVER
  pk.active = pk.active === false;
  persistPacks();
  showToast(pk.active ? `"${pk.name}" activé` : `"${pk.name}" désactivé`);
  render();
}
function duplicatePack(id) {
  const pk = S.packs.find(p => p.id === id);
  if (!pk) return;
  S.packs.unshift({ ...pk, id: Date.now(), name: pk.name + ' (copie)', createdAt: new Date().toISOString() });
  persistPacks();
  showToast('Pack dupliqué');
  render();
}
function startNewPack() {
  resetPackForm();
  S.view = 'pack-form';
  render();
}

// ── Unit combobox actions (DOM direct — zéro render() pendant la frappe) ──
function _unitDropHTML() {
  const q = (S.form.unit || '').toLowerCase();
  const safe = q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const filtered = UNITS.filter(u => u.toLowerCase().includes(q));
  if (!filtered.length) return `<div class="unit-opt" style="color:var(--text-3);cursor:default">${t('noResults')}</div>`;
  return filtered.map(u => {
    const hi = q ? u.replace(new RegExp(safe,'gi'), m => `<strong>${m}</strong>`) : u;
    return `<div class="unit-opt" onmousedown="event.preventDefault()" onclick="selectUnit('${u}')">${hi}</div>`;
  }).join('');
}
function openUnitDrop() {
  S.unitDropOpen = true;
  const wrap = document.getElementById('unit-combo-wrap');
  if (!wrap || document.getElementById('unit-dropdown')) return;
  const dd = document.createElement('div');
  dd.className = 'unit-dropdown'; dd.id = 'unit-dropdown';
  dd.innerHTML = _unitDropHTML();
  wrap.appendChild(dd);
}
function updateUnitDrop() {
  const inp = document.getElementById('unit-input');
  if (inp) S.form.unit = inp.value;
  const dd = document.getElementById('unit-dropdown');
  if (!dd) { openUnitDrop(); return; }
  dd.innerHTML = _unitDropHTML();
}
function closeUnitDrop() {
  S.unitDropOpen = false;
  const dd = document.getElementById('unit-dropdown');
  if (dd) dd.remove();
}
function selectUnit(u) {
  S.form.unit = u; S.unitDropOpen = false; S.unitCondVal = ''; S.unitCondOther = '';
  closeUnitDrop();
  render(); // re-render uniquement pour afficher/cacher la section conditionnelle
}
function selectUnitCond(v) { S.unitCondVal = v; S.unitCondOther = ''; render(); }

async function saveAccountInfo() {
  const nameVal  = ($('set-name')?.value  || '').trim();
  const bizVal   = ($('set-biz')?.value   || '').trim();
  const emailVal = ($('set-email')?.value || '').trim().toLowerCase();
  if (!nameVal) { showToast(t('nameRequired'), 'error'); return; }
  // L'e-mail est éditable ici → on valide le format et on garde le compte local cohérent
  if (emailVal && !EMAIL_RE.test(emailVal)) { showToast('E-mail invalide — format attendu : nom@exemple.com', 'error'); return; }
  const emailChanged = emailVal && emailVal !== (S.session.email || '').toLowerCase();
  if (emailChanged) {
    // Refuser si un autre compte local utilise déjà cet e-mail
    try {
      const taken = _lsUsers().some(u => u.email === emailVal && u.id !== S.session.id);
      if (taken) { showToast('Cet e-mail est déjà utilisé par un autre compte', 'error'); return; }
    } catch(_){}
  }
  try {
    await api('PUT', '/api/auth/profile', { name: nameVal, business_name: bizVal, ...(emailVal ? { email: emailVal } : {}) });
    S.session.name     = nameVal;
    S.session.business = bizVal;
    if (emailVal) S.session.email = emailVal;
    saveSession({ ...S.session, token: S.token });
    // Mettre à jour le compte local (baro_users_v2) pour que la connexion suive le nouvel e-mail
    try {
      const users = _lsUsers();
      const u = users.find(x => x.id === S.session.id);
      if (u) { u.name = nameVal; u.business_name = bizVal; if (emailVal) u.email = emailVal; _lsSave(users); }
    } catch(_){}
    S.settingsEdit = false;
    showToast(emailChanged ? '✓ Infos mises à jour — connectez-vous avec le nouvel e-mail' : t('infoUpdated'));
    render();
  } catch(e) {
    showToast(e.message, 'error');
  }
}

// Teste l'URL d'un backend BARO (/api/health) puis l'enregistre et recharge.
async function saveApiUrl() {
  const raw = ($('set-api-url')?.value || '').trim().replace(/\/+$/, '');
  if (!raw) { showToast('Entrez une URL (ou Réinitialiser pour revenir au défaut)', 'error'); return; }
  if (!/^https:\/\/[^\s]+$/i.test(raw)) { showToast('URL invalide — elle doit commencer par https://', 'error'); return; }
  showToast('🔎 Test du serveur…', '');
  try {
    const res = await fetch(raw + '/api/health', { method: 'GET' });
    const j = await res.json().catch(() => ({}));
    if (!res.ok || j.status !== 'healthy') throw new Error('Réponse inattendue (' + res.status + ')');
    localStorage.setItem('baro_api_url', raw);
    showToast('✅ Serveur connecté ! Rechargement…', 'success');
    setTimeout(() => location.reload(), 800);
  } catch(e) {
    showToast('❌ Serveur injoignable à cette URL : ' + (e.message || e), 'error');
  }
}

// Synchro manuelle : re-tire les données du serveur + re-pousse config/dépenses.
let _syncing = false;
async function syncNow() {
  if (_syncing) return;
  if (USE_LOCAL || !S.token) { showToast('Mode local — connectez un serveur dans « Serveur (API) »', 'info'); return; }
  _syncing = true;
  const btn = $('sync-now-btn');
  if (btn) { btn.disabled = true; btn.textContent = '⏳ Synchronisation…'; }
  try {
    await loadData();
    try { await _syncStoreBackup(); } catch(_){}
    showToast('☁️ Synchronisé', 'success');
  } catch(e) {
    showToast('Synchro impossible — réessayez plus tard', 'error');
  } finally {
    _syncing = false;
    render();
  }
}

// ── Lot 135 : synchro automatique EN LIGNE (reprise + périodique) ──
// Multi-appareils réel : les ventes des vendeurs, le stock et les commandes
// boutique apparaissent sur tous les téléphones SANS geste — au retour dans
// l'app et toutes les 3 minutes. Silencieuse et respectueuse : jamais pendant
// une saisie ni une vente en cours (pas de « blink »), au plus 1×/minute.
let _autoSyncLast = 0;
async function _autoSync() {
  if (_syncing || USE_LOCAL || !S.token) return;
  if (document.visibilityState !== 'visible') return;
  if (Date.now() - _autoSyncLast < 60000) return;
  const ae = document.activeElement;
  if (ae && (ae.tagName === 'INPUT' || ae.tagName === 'TEXTAREA' || ae.tagName === 'SELECT' || ae.isContentEditable)) return;
  if (document.querySelector('.qs-overlay')) return;   // vente / options en cours
  _autoSyncLast = Date.now();
  _syncing = true;
  try { await loadData(); } catch(_){}
  _syncing = false;
}
document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'visible') _autoSync(); });
setInterval(_autoSync, 180000);

// ── Sauvegarde / restauration par FICHIER (marche sans serveur) ──
// Migration d'appareil pour ceux qui ne déploient pas de backend :
// tout le localStorage BARO dans un .json, restaurable ailleurs.
function exportBackupFile() {
  try {
    const data = {};
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (/^(baro|stockr)_/.test(k)) data[k] = localStorage.getItem(k);
    }
    const payload = {
      _baro_backup: 1,
      version: (document.querySelector('script[src*="app.js"]')?.src.match(/v=([\w.-]+)/) || [])[1] || '?',
      exportedAt: new Date().toISOString(),
      business: S.session?.business || '',
      keys: Object.keys(data).length,
      data,
    };
    const blob = new Blob([JSON.stringify(payload)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    const stamp = new Date().toISOString().slice(0, 10);
    a.href = url;
    a.download = `baro_sauvegarde_${(S.session?.business || 'donnees').replace(/[^\w-]/g, '_').slice(0, 24)}_${stamp}.json`;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    showToast(`📦 Sauvegarde enregistrée (${payload.keys} éléments)`, 'success');
    logActivity('backup', 'Sauvegarde par fichier exportée');
  } catch (e) {
    showToast('Sauvegarde impossible : ' + (e.message || e), 'error');
  }
}

function importBackupFile(file) {
  if (!file) return;
  const reader = new FileReader();
  reader.onload = () => {
    let payload = null;
    try { payload = JSON.parse(reader.result); } catch (_) {}
    if (!payload || !payload._baro_backup || !payload.data || typeof payload.data !== 'object') {
      showToast('Fichier de sauvegarde invalide', 'error');
      return;
    }
    const n = Object.keys(payload.data).length;
    const when = payload.exportedAt ? new Date(payload.exportedAt).toLocaleString('fr-FR') : 'date inconnue';
    if (!confirm(`Restaurer cette sauvegarde ?\n\n${payload.business ? '🏪 ' + payload.business + '\n' : ''}📅 ${when}\n📦 ${n} éléments\n\n⚠️ Cela REMPLACE toutes les données actuelles de cet appareil.`)) return;
    try {
      // Purge des clés BARO existantes puis restauration intégrale
      const toRemove = [];
      for (let i = 0; i < localStorage.length; i++) { const k = localStorage.key(i); if (/^(baro|stockr)_/.test(k)) toRemove.push(k); }
      toRemove.forEach(k => localStorage.removeItem(k));
      Object.keys(payload.data).forEach(k => { try { localStorage.setItem(k, payload.data[k]); } catch (_) {} });
      showToast('✅ Données restaurées — redémarrage…', 'success');
      setTimeout(() => location.reload(), 1000);
    } catch (e) {
      showToast('Restauration impossible : ' + (e.message || e), 'error');
    }
  };
  reader.onerror = () => showToast('Lecture du fichier impossible', 'error');
  reader.readAsText(file);
}

function toggleDark() {
  S.darkMode = !S.darkMode;
  document.body.classList.toggle('dark', S.darkMode);
  // Support data-theme pour nouveaux styles dark
  if (S.darkMode) {
    document.documentElement.setAttribute('data-theme', 'dark');
    document.body.setAttribute('data-theme', 'dark');
  } else {
    document.documentElement.removeAttribute('data-theme');
    document.body.removeAttribute('data-theme');
  }
  // Persist preference
  localStorage.setItem('stockr_dark_mode', S.darkMode ? '1' : '0');
  showToast(S.darkMode ? 'Mode sombre activé' : 'Mode clair activé', 'success');
  render();
}

function applyTheme() {
  const saved = localStorage.getItem('stockr_dark_mode');
  if (saved === '1') {
    S.darkMode = true;
    document.body.classList.add('dark');
    document.documentElement.setAttribute('data-theme', 'dark');
    document.body.setAttribute('data-theme', 'dark');
  } else if (saved === '0') {
    S.darkMode = false;
  } else {
    // Auto: match system preference
    if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
      S.darkMode = true;
      document.body.classList.add('dark');
      document.documentElement.setAttribute('data-theme', 'dark');
      document.body.setAttribute('data-theme', 'dark');
    }
  }
}

