async function __vidRecordCamera() {
  try {
    const stream = await navigator.mediaDevices.getUserMedia({ video:{ facingMode:'environment' }, audio:true });
    __vidStartRecord(stream, 'camera');
  } catch(e) { showToast('Caméra refusée : '+e.message, 'error'); }
}

async function __vidRecordScreen() {
  try {
    const stream = await navigator.mediaDevices.getDisplayMedia({ video:true, audio:true });
    __vidStartRecord(stream, 'screen');
  } catch(e) { showToast('Enregistrement écran refusé', 'error'); }
}

function __vidStartRecord(stream, mode) {
  const wrap = document.getElementById('vid-preview-wrap');
  if (!wrap) return;
  const chunks = [];
  const rec = new MediaRecorder(stream, { mimeType: MediaRecorder.isTypeSupported('video/webm;codecs=vp9,opus') ? 'video/webm;codecs=vp9,opus' : 'video/webm' });
  rec.ondataavailable = e => { if (e.data.size) chunks.push(e.data); };
  rec.onstop = async () => {
    stream.getTracks().forEach(t => t.stop());
    const blob = new Blob(chunks, { type:'video/webm' });
    window.__lastVidBlob = blob;
    // Enregistrement automatique dans IndexedDB
    const id = await _vidSave(blob, { name: `BARO ${mode} ${new Date().toLocaleString('fr-FR')}`, source: mode });
    window.__lastVidId = id;
    const url = URL.createObjectURL(blob);
    const sizeKb = Math.round(blob.size / 1024);
    wrap.innerHTML = `
      <video src="${url}" controls style="width:100%;border-radius:10px;background:#000"></video>
      <div style="font-size:11px;color:var(--text-3);text-align:center;margin-top:6px">✅ Enregistrée automatiquement (${sizeKb} KB) — accessible dans "Mes vidéos"</div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px">
        <button class="btn btn-ghost" onclick="__vidDownload()">💾 Télécharger</button>
        <button class="btn btn-primary" onclick="__vidShare()">📤 Publier</button>
      </div>`;
    if (typeof logAudit === 'function') logAudit('settings', 'video_saved', { id, source: mode, size: blob.size });
    showToast(`🎞️ Vidéo enregistrée (${sizeKb} KB)`, 'success');
  };
  rec.start();
  wrap.innerHTML = `
    <div style="background:#000;border-radius:10px;padding:30px;text-align:center;color:#fff">
      <div style="font-size:40px;margin-bottom:10px;animation:pulse 1s infinite">🔴</div>
      <div style="font-size:14px;font-weight:700">Enregistrement ${mode}...</div>
    </div>
    <button class="btn btn-primary" style="width:100%;margin-top:10px;background:#DC2626" onclick="__vidStop()">⏹ Arrêter</button>`;
  window.__vidRec = rec;
}

function __vidStop() { try { window.__vidRec?.stop(); } catch(e){} }

// ── Enregistrement caméra avec TEXTE INCRUSTÉ (compositing canvas réel) ──
async function __vidRecordOverlay() {
  const text = (document.getElementById('vid-overlay-text')?.value || '').trim();
  if (!text) { showToast('Entrez le texte à incruster', 'info'); document.getElementById('vid-overlay-text')?.focus(); return; }
  let stream;
  try { stream = await navigator.mediaDevices.getUserMedia({ video:{ facingMode:'environment' }, audio:true }); }
  catch(e) { showToast('Caméra refusée : ' + e.message, 'error'); return; }
  __vidStartOverlayRecord(stream, text);
}
function __vidStartOverlayRecord(stream, text) {
  const wrap = document.getElementById('vid-preview-wrap');
  if (!wrap) { stream.getTracks().forEach(t=>t.stop()); return; }
  if (typeof HTMLCanvasElement === 'undefined' || !HTMLCanvasElement.prototype.captureStream) {
    showToast('Incrustation non supportée sur ce navigateur — caméra simple utilisée', 'info');
    __vidStartRecord(stream, 'camera'); return;
  }
  const video = document.createElement('video');
  video.srcObject = stream; video.muted = true; video.playsInline = true;
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');
  let raf = null, rec = null;
  const chunks = [];
  const start = () => {
    canvas.width = video.videoWidth || 720;
    canvas.height = video.videoHeight || 1280;
    const draw = () => {
      ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
      // Bandeau de texte incrusté (bas)
      const fs = Math.max(20, Math.round(canvas.width * 0.06));
      ctx.font = `800 ${fs}px Inter, Arial, sans-serif`;
      ctx.textAlign = 'center'; ctx.textBaseline = 'bottom';
      const pad = fs * 0.55;
      const barH = fs + pad * 1.6;
      const grad = ctx.createLinearGradient(0, canvas.height - barH, 0, canvas.height);
      grad.addColorStop(0, 'rgba(0,0,0,0)'); grad.addColorStop(0.4, 'rgba(0,0,0,.55)');
      ctx.fillStyle = grad; ctx.fillRect(0, canvas.height - barH, canvas.width, barH);
      ctx.fillStyle = '#fff';
      ctx.shadowColor = 'rgba(0,0,0,.6)'; ctx.shadowBlur = fs * 0.2; ctx.shadowOffsetY = 2;
      ctx.fillText(text, canvas.width / 2, canvas.height - pad);
      ctx.shadowBlur = 0; ctx.shadowOffsetY = 0;
      raf = requestAnimationFrame(draw);
    };
    draw();
    const cstream = canvas.captureStream(30);
    const at = stream.getAudioTracks()[0]; if (at) cstream.addTrack(at);
    const mime = MediaRecorder.isTypeSupported('video/webm;codecs=vp9,opus') ? 'video/webm;codecs=vp9,opus' : 'video/webm';
    rec = new MediaRecorder(cstream, { mimeType: mime });
    rec.ondataavailable = e => { if (e.data.size) chunks.push(e.data); };
    rec.onstop = async () => {
      if (raf) cancelAnimationFrame(raf);
      stream.getTracks().forEach(t => t.stop());
      const blob = new Blob(chunks, { type: 'video/webm' });
      window.__lastVidBlob = blob;
      const id = await _vidSave(blob, { name: `BARO texte « ${text.slice(0,24)} » ${new Date().toLocaleString('fr-FR')}`, source: 'overlay' });
      window.__lastVidId = id;
      const url = URL.createObjectURL(blob);
      const sizeKb = Math.round(blob.size / 1024);
      wrap.innerHTML = `
        <video src="${url}" controls style="width:100%;border-radius:10px;background:#000"></video>
        <div style="font-size:11px;color:var(--success);text-align:center;margin-top:6px">✅ Clip avec texte incrusté enregistré (${sizeKb} KB) — dans « Mes vidéos »</div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px">
          <button class="btn btn-ghost" onclick="__vidDownload()">💾 Télécharger</button>
          <button class="btn btn-primary" onclick="__vidShare()">📤 Publier</button>
        </div>`;
      showToast(`🎬 Clip avec texte incrusté prêt (${sizeKb} KB)`, 'success');
    };
    rec.start();
    window.__vidRec = rec;
    wrap.innerHTML = `
      <div style="background:#000;border-radius:10px;padding:30px;text-align:center;color:#fff">
        <div style="font-size:40px;margin-bottom:10px;animation:pulse 1s infinite">🔴</div>
        <div style="font-size:14px;font-weight:700">Enregistrement avec « ${text.replace(/</g,'&lt;')} »…</div>
      </div>
      <button class="btn btn-primary" style="width:100%;margin-top:10px;background:#DC2626" onclick="__vidStop()">⏹ Arrêter</button>`;
  };
  video.onloadedmetadata = () => { video.play().then(start).catch(start); };
}

async function __vidImport(e, source) {
  const file = e.target?.files?.[0];
  if (!file) return;
  window.__lastVidBlob = file;
  // Enregistrement automatique dans IndexedDB
  const id = await _vidSave(file, { name: file.name || `Import ${Date.now()}`, source: source || 'import' });
  window.__lastVidId = id;
  const url = URL.createObjectURL(file);
  const wrap = document.getElementById('vid-preview-wrap');
  if (wrap) {
    wrap.innerHTML = `
      <video src="${url}" controls style="width:100%;border-radius:10px;background:#000"></video>
      <div style="font-size:11px;color:var(--success);text-align:center;margin-top:6px">✅ ${source==='capcut'?'CapCut':'Vidéo'} importée et enregistrée</div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px">
        <button class="btn btn-ghost" onclick="__vidDownload()">💾 Télécharger</button>
        <button class="btn btn-primary" onclick="__vidShare()">📤 Publier</button>
      </div>`;
  }
  showToast(`🎞️ Vidéo importée${source==='capcut'?' depuis CapCut':''}`, 'success');
}

function __vidDownload() {
  if (!window.__lastVidBlob) return;
  const url = URL.createObjectURL(window.__lastVidBlob);
  const link = document.createElement('a');
  link.download = `baro-video-${Date.now()}.webm`;
  link.href = url;
  link.click();
  showToast('🎞️ Vidéo téléchargée', 'success');
}

async function __vidShare() {
  if (!window.__lastVidBlob) { showToast('Aucune vidéo', 'error'); return; }
  __openPublishDialog(window.__lastVidBlob, window.__lastVidId);
}

// ── Dialogue publication multi-plateformes ──
function __openPublishDialog(blob, vidId) {
  const existing = document.getElementById('publish-modal');
  if (existing) existing.remove();
  const url = URL.createObjectURL(blob);
  const modal = document.createElement('div');
  modal.id = 'publish-modal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.85);z-index:10002;display:flex;align-items:center;justify-content:center;padding:12px;backdrop-filter:blur(6px);animation:fadeIn .2s ease';
  modal.innerHTML = `
    <div style="background:var(--surface);border-radius:16px;max-width:430px;width:100%;max-height:94vh;overflow-y:auto;box-shadow:0 25px 60px rgba(0,0,0,.5);animation:slideUp .25s ease">
      <div style="padding:14px 18px;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between">
        <div style="font-size:16px;font-weight:800;color:var(--text-1)">📤 Publier la vidéo</div>
        <button style="width:30px;height:30px;border-radius:50%;border:none;background:var(--gray-1);color:var(--text-2);font-size:16px;cursor:pointer" onclick="document.getElementById('publish-modal').remove()">×</button>
      </div>
      <div style="padding:14px 18px">
        <video src="${url}" controls style="width:100%;border-radius:10px;background:#000;max-height:220px;margin-bottom:12px"></video>
        <label class="form-label">Légende</label>
        <textarea id="publish-caption" class="input" rows="3" placeholder="Décrivez votre vidéo..." style="font-size:14px !important">${S.business?.name ? `🔥 Nouveau chez ${S.business.name} ! ` : ''}#BARO #PME</textarea>

        <div style="margin-top:14px;font-size:13px;font-weight:700;color:var(--text-1);margin-bottom:8px">🌐 Partager vers</div>
        <div style="display:grid;grid-template-columns:repeat(2,1fr);gap:8px">
          <button class="btn" style="background:linear-gradient(135deg,#833AB4,#E1306C);color:#fff;padding:12px;font-size:12px;font-weight:700" onclick="__publishTo('instagram')">📷 Instagram</button>
          <button class="btn" style="background:linear-gradient(135deg,#000,#25F4EE);color:#fff;padding:12px;font-size:12px;font-weight:700" onclick="__publishTo('tiktok')">🎵 TikTok</button>
          <button class="btn" style="background:#FF0000;color:#fff;padding:12px;font-size:12px;font-weight:700" onclick="__publishTo('youtube')">▶️ YouTube</button>
          <button class="btn" style="background:#1877F2;color:#fff;padding:12px;font-size:12px;font-weight:700" onclick="__publishTo('facebook')">f Facebook</button>
          <button class="btn" style="background:#000;color:#fff;padding:12px;font-size:12px;font-weight:700" onclick="__publishTo('twitter')">𝕏 X (Twitter)</button>
          <button class="btn" style="background:#25D366;color:#fff;padding:12px;font-size:12px;font-weight:700" onclick="__publishTo('whatsapp')">💬 WhatsApp</button>
        </div>

        <button class="btn btn-primary" style="width:100%;margin-top:12px;padding:14px;font-weight:800" onclick="__publishTo('share')">📤 Partager (système)</button>
        <button class="btn btn-ghost" style="width:100%;margin-top:6px" onclick="__publishTo('download')">💾 Télécharger uniquement</button>
        <div style="background:var(--accent-light);border-radius:10px;padding:10px;margin-top:10px;font-size:11px;color:var(--text-2);line-height:1.5">
          💡 Pour IG/TikTok/YouTube/FB : le partage ouvre l'app native avec la vidéo + la légende copiée. Collez-la dans la description.
        </div>
      </div>
    </div>`;
  document.body.appendChild(modal);
  window.__publishBlob = blob;
  window.__publishVidId = vidId;
}

async function __publishTo(target) {
  const caption = document.getElementById('publish-caption')?.value || '';
  const blob = window.__publishBlob;
  if (!blob) { showToast('Aucune vidéo', 'error'); return; }
  const file = new File([blob], `baro-${Date.now()}.webm`, { type: blob.type || 'video/webm' });

  // Copie la légende pour que l'utilisateur puisse la coller (fallback)
  if (caption) {
    try { await navigator.clipboard.writeText(caption); } catch(e){}
  }

  // Historique publication
  try {
    const hist = JSON.parse(localStorage.getItem('stockr_publish_history') || '[]');
    hist.unshift({ vidId: window.__publishVidId, target, caption, ts: Date.now() });
    localStorage.setItem('stockr_publish_history', JSON.stringify(hist.slice(0, 200)));
  } catch(e){}
  if (typeof logAudit === 'function') logAudit('settings', 'video_published', { target, vidId: window.__publishVidId });

  // ═══ Download direct ═══
  if (target === 'download') {
    __vidDownload();
    return;
  }

  // ═══ YouTube : upload RÉEL via Data API v3 ═══
  if (target === 'youtube') {
    const clientId = (localStorage.getItem('stockr_google_client_id') || '').trim();
    if (!clientId) {
      if (confirm('Google OAuth non configuré. Configurer maintenant ?')) {
        document.getElementById('publish-modal')?.remove();
        nav('oauth-setup');
      }
      return;
    }
    showToast('📤 Upload YouTube en cours... (1-5 min)', 'info');
    try {
      const result = await uploadVideoToYouTube(blob, 'BARO — ' + new Date().toLocaleDateString(), caption);
      if (result?.id) {
        showToast('✅ Publié : youtube.com/watch?v=' + result.id, 'success');
        window.open('https://studio.youtube.com/video/' + result.id + '/edit', '_blank');
        document.getElementById('publish-modal')?.remove();
      }
    } catch(e) {
      showToast('❌ Upload YouTube échoué : ' + e.message, 'error');
    }
    return;
  }

  // ═══ Facebook : upload RÉEL via Graph API /me/videos ═══
  if (target === 'facebook') {
    const fbToken = (localStorage.getItem('stockr_fb_token') || '').trim();
    const fbPageId = (localStorage.getItem('stockr_fb_page_id') || '').trim();
    if (!fbToken) {
      if (confirm('Token Facebook Graph API non configuré. Configurer maintenant ?\n\n(Obtenir un token : https://developers.facebook.com/tools/explorer — permissions pages_manage_posts, pages_read_engagement)')) {
        const tok = prompt('Collez votre Facebook Page Access Token (pas le User token) :');
        if (tok) {
          localStorage.setItem('stockr_fb_token', tok.trim());
          const pid = prompt('Page ID Facebook (optionnel, laissez vide pour "me") :');
          if (pid) localStorage.setItem('stockr_fb_page_id', pid.trim());
          showToast('Token FB enregistré, réessayez', 'info');
        }
      }
      return;
    }
    showToast('📤 Upload Facebook en cours...', 'info');
    try {
      const result = await uploadVideoToFacebook(blob, caption, fbToken, fbPageId);
      if (result?.id) {
        showToast('✅ Publié sur Facebook (ID ' + result.id + ')', 'success');
        window.open('https://www.facebook.com/' + (fbPageId||'me'), '_blank');
        document.getElementById('publish-modal')?.remove();
      }
    } catch(e) {
      showToast('❌ Upload FB échoué : ' + e.message, 'error');
    }
    return;
  }

  // ═══ Instagram : upload RÉEL via Graph API (Reels) ═══
  if (target === 'instagram') {
    const igToken = (localStorage.getItem('stockr_ig_token') || '').trim();
    const igBusinessId = (localStorage.getItem('stockr_ig_business_id') || '').trim();
    if (!igToken || !igBusinessId) {
      if (confirm('Instagram Graph API non configuré.\n\nInstagram nécessite un compte Business + token FB Page + IG Business ID.\nConfigurer maintenant ?')) {
        const tok = prompt('Access Token (même que Facebook Page Token) :');
        const bid = tok ? prompt('Instagram Business Account ID (17 chiffres) :') : null;
        if (tok && bid) {
          localStorage.setItem('stockr_ig_token', tok.trim());
          localStorage.setItem('stockr_ig_business_id', bid.trim());
          showToast('IG configuré, réessayez', 'info');
        }
      }
      // Fallback : partage natif (mobile)
      if (navigator.canShare && navigator.canShare({ files:[file] })) {
        try {
          await navigator.share({ files:[file], title:'BARO', text: caption });
          showToast('✅ Partagé (choisissez Instagram)', 'success');
          document.getElementById('publish-modal')?.remove();
          return;
        } catch(e){ if (e.name === 'AbortError') return; }
      }
      return;
    }
    showToast('📤 Upload Instagram Reel en cours... (2-4 min)', 'info');
    try {
      const result = await uploadVideoToInstagram(blob, caption, igToken, igBusinessId);
      if (result?.id) {
        showToast('✅ Reel publié sur Instagram', 'success');
        window.open('https://www.instagram.com/', '_blank');
        document.getElementById('publish-modal')?.remove();
      }
    } catch(e) {
      showToast('❌ Upload IG échoué : ' + e.message, 'error');
    }
    return;
  }

  // ═══ TikTok / Twitter / WhatsApp / share : Web Share API natif (mobile) ═══
  // Sur mobile, ça ouvre la feuille de partage → utilisateur choisit l'app → fichier importé directement.
  // Sur desktop : download + ouvre le VRAI compte connecté (upload.tiktok.com, x.com/compose, web.whatsapp.com)
  if (navigator.canShare && navigator.canShare({ files:[file] })) {
    try {
      await navigator.share({ files:[file], title:'BARO', text: caption });
      showToast('✅ Partagé via ' + target, 'success');
      document.getElementById('publish-modal')?.remove();
      return;
    } catch(e) {
      if (e.name === 'AbortError') return;
    }
  }

  // Desktop : télécharge + ouvre la VRAIE page du compte (login requis sur la plateforme)
  const platformUrls = {
    tiktok:    'https://www.tiktok.com/upload?lang=fr',      // page d'upload officielle (login requis)
    twitter:   'https://x.com/compose/post',                  // compose un post sur X
    whatsapp:  'https://web.whatsapp.com/',                   // WhatsApp Web (login via QR)
    share:     null,
  };
  __vidDownload();
  if (platformUrls[target]) {
    // Délai court pour laisser le téléchargement démarrer, puis ouvrir l'onglet
    setTimeout(() => {
      try { window.open(platformUrls[target], '_blank', 'noopener'); } catch(_){}
    }, 500);
    const tips = {
      tiktok: 'TikTok : glissez la vidéo téléchargée → collez la légende (déjà dans le presse-papiers)',
      twitter: 'X : cliquez "Médias" → sélectionnez la vidéo téléchargée → la légende est déjà copiée',
      whatsapp: 'WhatsApp : pièce jointe → choisissez la vidéo téléchargée → collez la légende',
    };
    showToast('📥 Téléchargée + ' + (tips[target] || 'importez manuellement'), 'success');
  } else {
    showToast('📥 Téléchargée — importez dans l\'app de votre choix', 'info');
  }
}

// ── Facebook Graph API v18 — upload vidéo RÉEL ─────────
// Doc : https://developers.facebook.com/docs/graph-api/reference/video
async function uploadVideoToFacebook(blob, description, accessToken, pageId) {
  const endpoint = 'https://graph-video.facebook.com/v18.0/' + (pageId || 'me') + '/videos';
  const fd = new FormData();
  fd.append('source', blob, 'baro.webm');
  fd.append('description', description || '');
  fd.append('access_token', accessToken);
  const res = await fetch(endpoint, { method: 'POST', body: fd });
  if (!res.ok) {
    const err = await res.text().catch(()=>String(res.status));
    throw new Error('FB ' + res.status + ' : ' + err.slice(0, 200));
  }
  return await res.json();
}

// ── Instagram Graph API v18 — upload Reel en 2 étapes ──
// 1) Créer un media container avec l'URL de la vidéo
// 2) Publier le container
// NOTE : Instagram exige une URL publique (pas un blob local). On passe donc par un hébergement.
// Solution : uploader d'abord sur un storage (ici on demande l'URL manuellement, ou on utilise Cloudinary si configuré).
async function uploadVideoToInstagram(blob, caption, accessToken, igBusinessId) {
  // Instagram n'accepte pas les uploads directs par multipart — il faut une URL publique.
  // Option 1 : Cloudinary (gratuit 25 crédits/mois)
  // Option 2 : Facebook hébergement temporaire via le container Reel
  // On utilise la v2 resumable upload qui accepte les bytes directement.
  const createRes = await fetch('https://graph.facebook.com/v18.0/' + igBusinessId + '/media?' +
    new URLSearchParams({
      media_type: 'REELS',
      upload_type: 'resumable',
      caption: caption || '',
      access_token: accessToken,
    }), { method: 'POST' });
  if (!createRes.ok) {
    const err = await createRes.text().catch(()=>String(createRes.status));
    throw new Error('IG create container ' + createRes.status + ' : ' + err.slice(0,200));
  }
  const { id: containerId, uri: uploadUri } = await createRes.json();
  if (!uploadUri) throw new Error('IG : pas d\'URI de upload');

  // Upload resumable : PUT avec offset
  const fileSize = blob.size;
  const putRes = await fetch(uploadUri, {
    method: 'POST',
    headers: {
      'Authorization': 'OAuth ' + accessToken,
      'offset': '0',
      'file_size': String(fileSize),
    },
    body: blob,
  });
  if (!putRes.ok) {
    const err = await putRes.text().catch(()=>String(putRes.status));
    throw new Error('IG upload ' + putRes.status + ' : ' + err.slice(0,200));
  }

  // Poll statut container (prêt à publier)
  for (let i = 0; i < 30; i++) {
    await new Promise(r => setTimeout(r, 4000));
    const statusRes = await fetch('https://graph.facebook.com/v18.0/' + containerId + '?fields=status_code&access_token=' + accessToken);
    const statusJson = await statusRes.json();
    if (statusJson.status_code === 'FINISHED') break;
    if (statusJson.status_code === 'ERROR') throw new Error('IG container status ERROR');
  }

  // Publier le Reel
  const publishRes = await fetch('https://graph.facebook.com/v18.0/' + igBusinessId + '/media_publish?' +
    new URLSearchParams({ creation_id: containerId, access_token: accessToken }), { method: 'POST' });
  if (!publishRes.ok) {
    const err = await publishRes.text().catch(()=>String(publishRes.status));
    throw new Error('IG publish ' + publishRes.status + ' : ' + err.slice(0,200));
  }
  return await publishRes.json();
}

// ── CapCut round-trip flow ──
function openCapCutFlow() {
  const existing = document.getElementById('capcut-modal');
  if (existing) existing.remove();
  const modal = document.createElement('div');
  modal.id = 'capcut-modal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.85);z-index:10003;display:flex;align-items:center;justify-content:center;padding:12px;backdrop-filter:blur(6px);animation:fadeIn .2s ease';
  modal.innerHTML = `
    <div style="background:var(--surface);border-radius:16px;max-width:430px;width:100%;max-height:94vh;overflow-y:auto;box-shadow:0 25px 60px rgba(0,0,0,.5);animation:slideUp .25s ease">
      <div style="padding:14px 18px;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between;background:linear-gradient(135deg,#000,#25F4EE);color:#fff">
        <div style="font-size:16px;font-weight:800">✨ Flow CapCut</div>
        <button style="width:30px;height:30px;border-radius:50%;border:none;background:rgba(255,255,255,.2);color:#fff;font-size:16px;cursor:pointer" onclick="document.getElementById('capcut-modal').remove()">×</button>
      </div>
      <div style="padding:16px 18px">
        <div style="font-size:13px;color:var(--text-2);line-height:1.6;margin-bottom:14px">
          <strong>Workflow BARO × CapCut :</strong><br>
          1️⃣ Exportez/téléchargez une vidéo BARO<br>
          2️⃣ Ouvrez CapCut, ajoutez transitions/effets/musique<br>
          3️⃣ Exportez en MP4/WebM<br>
          4️⃣ Re-importez ici pour publier sur les réseaux
        </div>

        <div style="display:grid;gap:10px">
          <a href="https://www.capcut.com/editor" target="_blank" rel="noopener noreferrer" class="btn" style="background:linear-gradient(135deg,#000,#25F4EE);color:#fff;padding:14px;font-weight:700;text-decoration:none;text-align:center;display:block">🌐 Ouvrir CapCut Web</a>
          <a href="capcut://" class="btn btn-ghost" style="padding:14px;text-align:center;text-decoration:none;display:block" onclick="setTimeout(()=>{if(document.hasFocus())window.open('https://www.capcut.com/','_blank')},500)">📱 Ouvrir app CapCut (mobile)</a>
          <label class="btn btn-primary" style="padding:14px;cursor:pointer;display:block;text-align:center">
            📁 Ré-importer vidéo CapCut
            <input type="file" accept="video/*" style="display:none" onchange="__vidImport(event,'capcut');document.getElementById('capcut-modal').remove()">
          </label>
          ${window.__lastVidBlob ? `<button class="btn btn-ghost" onclick="__vidDownload()">💾 Télécharger vidéo actuelle (pour CapCut)</button>` : ''}
        </div>

        <div style="background:var(--accent-light);border-radius:10px;padding:10px;margin-top:14px;font-size:11px;color:var(--text-2);line-height:1.5">
          💡 Astuce : sur mobile, CapCut s'ouvre automatiquement si installé.
        </div>
      </div>
    </div>`;
  document.body.appendChild(modal);
}

