async function __confirmYTUpload() {
  const id = document.getElementById('yt-vid-select')?.value;
  const title = document.getElementById('yt-title')?.value;
  const desc = document.getElementById('yt-desc')?.value;
  if (!id) return;
  const rec = await _vidLoad(id);
  if (!rec) { showToast('Vidéo introuvable', 'error'); return; }
  document.getElementById('yt-upload-modal')?.remove();
  showToast('📤 Upload YouTube en cours... (peut prendre 1-5 min)', 'info');
  try {
    const result = await uploadVideoToYouTube(rec.blob, title, desc);
    if (result?.id) {
      showToast('✅ Uploadée : youtube.com/watch?v=' + result.id, 'success');
      window.open('https://studio.youtube.com/video/' + result.id + '/edit', '_blank');
      if (typeof logAudit === 'function') logAudit('settings', 'youtube_upload', { videoId: result.id });
    } else {
      showToast('Upload effectué mais réponse inattendue', 'info');
    }
  } catch(e) {
    showToast('❌ Upload échoué : ' + e.message, 'error');
  }
}

// ── YouTube Data API v3 — upload réel (nécessite OAuth token) ─
async function uploadVideoToYouTube(blob, title, description) {
  // Utilise le Google OAuth déjà configuré pour obtenir un access_token avec scope youtube.upload
  const clientId = (localStorage.getItem('stockr_google_client_id') || '').trim();
  if (!clientId) {
    showToast('Configurez d\'abord Google OAuth (Connexions OAuth)', 'error');
    return;
  }
  try {
    await _loadGoogleGSI();
    return await new Promise((resolve, reject) => {
      const tokenClient = window.google.accounts.oauth2.initTokenClient({
        client_id: clientId,
        scope: 'https://www.googleapis.com/auth/youtube.upload',
        callback: async (tok) => {
          if (!tok.access_token) { reject(new Error('No token')); return; }
          try {
            const metadata = {
              snippet: { title: title || 'BARO Video', description: description || '', tags: ['BARO', 'PME'], categoryId: '22' },
              status: { privacyStatus: 'unlisted' }  // Non répertorié : accessible via lien, modifiable dans Studio
            };
            const boundary = '-------314159265358979323846';
            const delim = `\r\n--${boundary}\r\n`;
            const closeDelim = `\r\n--${boundary}--`;
            const reader = new FileReader();
            reader.onload = async () => {
              const b64 = reader.result.split(',')[1];
              const body = delim +
                'Content-Type: application/json; charset=UTF-8\r\n\r\n' +
                JSON.stringify(metadata) +
                delim +
                'Content-Type: video/webm\r\n' +
                'Content-Transfer-Encoding: base64\r\n\r\n' +
                b64 +
                closeDelim;
              const res = await fetch('https://www.googleapis.com/upload/youtube/v3/videos?uploadType=multipart&part=snippet,status', {
                method: 'POST',
                headers: {
                  'Authorization': 'Bearer ' + tok.access_token,
                  'Content-Type': `multipart/related; boundary=${boundary}`,
                },
                body
              });
              if (!res.ok) { reject(new Error('YouTube ' + res.status)); return; }
              const json = await res.json();
              resolve(json);
            };
            reader.readAsDataURL(blob);
          } catch(e) { reject(e); }
        },
      });
      tokenClient.requestAccessToken({ prompt: 'consent' });
    });
  } catch(e) {
    showToast('Erreur upload YouTube : ' + e.message, 'error');
    throw e;
  }
}

function _getIntegrationDef(id) {
  const defs = {
    'whatsapp-business': { setupType:'whatsapp-setup', setupLabel:'Numero WhatsApp Business', setupPlaceholder:'+225 07 XX XX XX XX', url:'https://business.facebook.com/wa/manage/', docUrl:'https://developers.facebook.com/docs/whatsapp/cloud-api/' },
    'sms-api':           { setupType:'sms-setup', setupLabel:'Configuration passerelle SMS', setupPlaceholder:'Twilio, Vonage, Africa\'s Talking...', docUrl:'https://www.twilio.com/docs/sms' },
    'woocommerce':       { setupType:'url+key', setupLabel:'URL boutique WooCommerce', setupPlaceholder:'https://maboutique.com', keyLabel:'Cle API WooCommerce' },
    'shopify':           { setupType:'url+key', setupLabel:'URL boutique Shopify', setupPlaceholder:'https://maboutique.myshopify.com', keyLabel:'Access Token', url:'https://www.shopify.com/admin' },
    'jumia':             { setupType:'url', setupLabel:'Lien vendeur Jumia', setupPlaceholder:'https://vendorcenter.jumia.com/', url:'https://vendorcenter.jumia.com/' },
    'glovo':             { setupType:'delivery-oauth', setupLabel:'Connexion Glovo Partners', url:'https://sell.glovoapp.com/', docUrl:'https://api-docs.glovoapp.com/' },
    'yango':             { setupType:'delivery-oauth', setupLabel:'Connexion Yango Delivery', url:'https://delivery.yango.com/', docUrl:'https://delivery.yango.com/docs' },
    'yango-deli':        { setupType:'account', setupLabel:'ID Partenaire Yango Deli', setupPlaceholder:'YDL-XXXXX', url:'https://deli.yango.com/', docUrl:'https://deli.yango.com/partners' },
    'yango-market':      { setupType:'account', setupLabel:'ID Vendeur Yango Market', setupPlaceholder:'YMK-XXXXX', url:'https://market.yango.com/', docUrl:'https://market.yango.com/seller' },
    'wave':              { setupType:'phone', setupLabel:'Numéro Wave Business', setupPlaceholder:'+225 07 00 00 00 00', url:'https://www.wave.com/fr/business/', docUrl:'https://www.wave.com/fr/business/docs' },
    'youtube-studio':    { setupType:'url', setupLabel:'URL chaîne YouTube', setupPlaceholder:'https://youtube.com/@mashop', url:'https://studio.youtube.com/', docUrl:'https://support.google.com/youtube/topic/9257610' },
    'google-sheets':     { setupType:'url', setupLabel:'URL Google Sheet partagee', setupPlaceholder:'https://docs.google.com/spreadsheets/d/...' },
    'excel':             { setupType:'action' },
    'comptabilite':      { setupType:'action' },
    'pos':               { setupType:'serial', setupLabel:'ID Terminal POS', setupPlaceholder:'POS-XXXXXX' },
  };
  return defs[id] || {};
}

function connectIntegration(integrationId) {
  const def = _getIntegrationDef(integrationId);
  const names = {'whatsapp-business':'WhatsApp Business','sms-api':'SMS API','woocommerce':'WooCommerce','shopify':'Shopify','jumia':'Jumia','glovo':'Glovo','yango':'Yango Delivery','google-sheets':'Google Sheets','excel':'Excel','comptabilite':'Comptabilite','pos':'Caisse POS'};
  const name = names[integrationId] || integrationId;

  // Comptabilité OHADA → vue dédiée (push temps réel + SYSCOHADA)
  if (integrationId === 'comptabilite') {
    nav('compta-setup');
    return;
  }
  // POS / Caisse → vue dédiée (ESC/POS + tiroir)
  if (integrationId === 'pos') {
    nav('pos-setup');
    return;
  }
  // Excel — action flow (export CSV)
  if (def.setupType === 'action') {
    if (integrationId === 'excel') {
      exportAllCSV();
      _saveIntegration(integrationId, name, 'Export CSV active');
      return;
    }
  }

  // Livraison Glovo/Yango → vue de configuration dédiée (formulaire complet)
  if (integrationId === 'glovo' || integrationId === 'yango') {
    S.deliverySetupProvider = integrationId;
    nav('delivery-setup');
    return;
  }

  // WhatsApp Business Cloud API → vue dédiée
  if (integrationId === 'whatsapp-business') {
    nav('whatsapp-setup');
    return;
  }

  // SMS API multi-providers → vue dédiée
  if (integrationId === 'sms-api') {
    nav('sms-setup');
    return;
  }

  // E-commerce (Shopify / WooCommerce / Jumia) → vue dédiée avec sync temps réel
  if (['shopify','woocommerce','jumia'].includes(integrationId)) {
    S.ecommerceSetupProvider = integrationId;
    nav('ecommerce-setup');
    return;
  }

  // Google Sheets → vue dédiée (API v4 append temps réel)
  if (integrationId === 'google-sheets') {
    nav('sheets-setup');
    return;
  }

  // Open partner URL if available
  if (def.url) {
    if (confirm(`Ouvrir ${name} dans un nouvel onglet pour recuperer vos identifiants ?`)) {
      window.open(def.url, '_blank');
    }
  }

  // Collect credentials
  if (def.setupType === 'phone') {
    const phone = prompt(def.setupLabel + ' :', def.setupPlaceholder);
    if (!phone || phone === def.setupPlaceholder) return;
    _saveIntegration(integrationId, name, phone);
  } else if (def.setupType === 'apikey') {
    const key = prompt(def.setupLabel + ' :', '');
    if (!key) return;
    _saveIntegration(integrationId, name, '****' + key.slice(-4), key);
  } else if (def.setupType === 'url+key') {
    const url = prompt(def.setupLabel + ' :', def.setupPlaceholder);
    if (!url || url === def.setupPlaceholder) return;
    const apiKey = prompt((def.keyLabel||'Cle API') + ' :', '');
    if (!apiKey) return;
    _saveIntegration(integrationId, name, url, apiKey);
  } else if (def.setupType === 'url') {
    const url = prompt(def.setupLabel + ' :', def.setupPlaceholder);
    if (!url || url === def.setupPlaceholder) return;
    _saveIntegration(integrationId, name, url);
  } else if (def.setupType === 'account' || def.setupType === 'serial') {
    const val = prompt(def.setupLabel + ' :', def.setupPlaceholder);
    if (!val || val === def.setupPlaceholder) return;
    _saveIntegration(integrationId, name, val);
  }
}

function _saveIntegration(id, name, displayValue, secretKey) {
  const existing = S.integrationsConfig.findIndex(i => i.id === id);
  const entry = { id, name, connected:true, value:displayValue, key:secretKey||null, date:new Date().toISOString() };
  if (existing >= 0) S.integrationsConfig[existing] = entry;
  else S.integrationsConfig.push(entry);
  localStorage.setItem('baro_integrations', JSON.stringify(S.integrationsConfig));
  logActivity('integration', `${name} connecte`);
  showToast(`${name} connecte avec succes !`);
  render();
}

function disconnectIntegration(id, name) {
  if (!confirm(`Deconnecter ${name} ?`)) return;
  S.integrationsConfig = S.integrationsConfig.filter(i => i.id !== id);
  localStorage.setItem('baro_integrations', JSON.stringify(S.integrationsConfig));
  showToast(`${name} deconnecte`);
  render();
}

